/**
 * Miltank Farm (Kalos Route 12) — idle Moomoo Milk production + feed requests.
 */

export type MiltankFarmRequestCategory = 'common' | 'medium' | 'rare' | 'premium';

export interface MiltankFarmRequestDef {
    itemKey: string;
    qty: number;
    weight: number;
    category: MiltankFarmRequestCategory;
}

export const MILTANK_FARM_ZONE_ID = 523;
export const MILTANK_FARM_VILLAGE_ZONE_ID = 539;
export const NARRATIVE_MILTANK_UID = 'narrative';

export const MILTANK_FARM = Object.freeze({
    offlineCapMs: 48 * 60 * 60 * 1000,
    requestRotationMs: 8 * 60 * 60 * 1000,
    feedBoostDurationMs: 2 * 60 * 60 * 1000,
    feedBoostMult: 1.5,
    baseMilkPerHour: 0.18,
    baseStockCap: 2,
    levelStockBonus: 1,
    pastureStockBonus: 1,
    perMiltankStockCap: 2,
    assignedMiltankRateMults: Object.freeze([0.6, 0.45]),
    rerollCostPokedollars: 5000,
    satietyMax: 100,
    satietyDecayPerHour: 6,
});

import { buildMiltankFarmRequestPool } from '../../src/lib/miltankFarmRequestPool.ts';

export const MILTANK_FARM_REQUEST_POOL_MANUAL: MiltankFarmRequestDef[] = [
    { itemKey: 'super_potion', qty: 2, weight: 22, category: 'common' },
    { itemKey: 'full_restore', qty: 1, weight: 14, category: 'common' },
    { itemKey: 'attaque_plus', qty: 2, weight: 12, category: 'medium' },
    { itemKey: 'defense_plus', qty: 2, weight: 12, category: 'medium' },
    { itemKey: 'pv_plus', qty: 1, weight: 8, category: 'rare' },
    { itemKey: 'proteine', qty: 1, weight: 8, category: 'rare' },
    { itemKey: 'calcium', qty: 1, weight: 6, category: 'rare' },
    { itemKey: 'super_bonbon', qty: 1, weight: 3, category: 'premium' },
];

Object.freeze(MILTANK_FARM_REQUEST_POOL_MANUAL);

export const MILTANK_FARM_REQUEST_POOL: MiltankFarmRequestDef[] =
    buildMiltankFarmRequestPool(MILTANK_FARM_REQUEST_POOL_MANUAL);

Object.freeze(MILTANK_FARM_REQUEST_POOL);

export function getMiltankFarmStockCap(
    level: number,
    pastureUpgraded: boolean,
): number {
    let cap = MILTANK_FARM.baseStockCap;
    if (level >= 1) cap += MILTANK_FARM.levelStockBonus;
    if (pastureUpgraded) cap += MILTANK_FARM.pastureStockBonus;
    return cap;
}
