/**
 * Tooltip HTML for berry tree mulch rows (effect, duration, stock).
 */

import { BERRY_MULCHES } from '../../constants/balance/berryTree.ts';
import { escapeHtml } from '../../formatters.ts';
import type { GameRuntime } from '../types/game.js';
import { formatFarmDuration } from './miltankFarmDisplay.ts';

export type BerryTreeMulchTooltipInput = {
    mulchKey: string;
    displayName: string;
    iconUrl: string | null;
    owned: number;
    description: string;
};

function getLang(game: GameRuntime | null | undefined): 'fr' | 'en' {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : (game?.language === 'en' ? 'en' : 'fr');
    return lang === 'en' ? 'en' : 'fr';
}

function farmT(
    game: GameRuntime | null | undefined,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = getLang(game);
    if (game && typeof game.t === 'function') {
        const out = game.t(key, vars);
        if (out && out !== key) return out;
    }
    const template = lang === 'en' ? fallbackEn : fallbackFr;
    return template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));
}

function formatEffectLabel(game: GameRuntime | null | undefined, mulchKey: string): string {
    const def = BERRY_MULCHES[mulchKey];
    if (!def) return '';

    if (def.effect.type === 'berryProductionBoost') {
        const mult = Math.max(1, Number(def.effect.mult) || 1);
        return farmT(
            game,
            'berryTree.boostSpeedMult',
            '×{mult} vitesse de production',
            '×{mult} production speed',
            { mult: mult % 1 === 0 ? mult : mult.toFixed(2) },
        );
    }

    const pct = Math.round(Math.max(0, Math.min(1, Number(def.effect.bonusBerryChance) || 0)) * 100);
    return farmT(
        game,
        'berryTree.boostBonusChance',
        '+{pct} % baie bonus',
        '+{pct}% bonus berry',
        { pct },
    );
}

export function buildBerryTreeMulchTooltipContent(
    game: GameRuntime | null | undefined,
    input: BerryTreeMulchTooltipInput,
): { title: string; body: string } {
    const safeInput = input || ({} as BerryTreeMulchTooltipInput);
    const def = BERRY_MULCHES[safeInput.mulchKey];
    const durationMs = def?.effect?.duration ?? 0;
    const durationLabel = farmT(
        game,
        'berryTree.mulchTooltipDuration',
        'Durée : {time}',
        'Duration: {time}',
        { time: formatFarmDuration(durationMs, getLang(game)) },
    );
    const rawOwned = Number(safeInput.owned);
    const safeOwned = Number.isFinite(rawOwned) ? Math.max(0, Math.floor(rawOwned)) : 0;
    const ownedLabel = farmT(
        game,
        'berryTree.mulchTooltipOwned',
        'En sac : ×{count}',
        'In bag: ×{count}',
        { count: safeOwned },
    );
    const effectLabel = formatEffectLabel(game, safeInput.mulchKey);

    const icon = safeInput.iconUrl
        ? `<img class="miltank-farm-feed-tooltip-icon item-sprite-img" src="${escapeHtml(safeInput.iconUrl)}" alt="" width="36" height="36" loading="lazy" decoding="async">`
        : '';
    const name = escapeHtml(safeInput.displayName || '');

    const parts: string[] = [
        `<div class="miltank-farm-feed-tooltip-line">${icon}<span class="miltank-farm-feed-tooltip-text"><strong>${name}</strong></span></div>`,
    ];

    if (effectLabel) {
        parts.push(escapeHtml(effectLabel));
    }
    if (durationLabel) {
        parts.push(escapeHtml(durationLabel));
    }
    parts.push(escapeHtml(ownedLabel));

    const description = (safeInput.description || '').trim();
    if (description) {
        parts.push(escapeHtml(description));
    }

    return {
        title: name,
        body: parts.join('<br>'),
    };
}
