import { RARITY } from '../../constants/core.ts';
import type { GameRuntime } from '../types/game.js';
import { getItemIconPath } from '../ui/utils.ts';
import {
    BAG_INVENTORY_CATEGORY_I18N_KEYS,
    BAG_INVENTORY_CATEGORY_ORDER,
    resolveBagItemInventoryCategory,
    type BagInventoryCategory,
} from './bagItemFilters.ts';

export type TowerLootItemDef = {
    name?: string;
    img?: string;
    icon?: string;
    rarity?: string;
    type?: string;
    effect?: Record<string, unknown> | null;
    evolutionItem?: boolean;
};

export interface TowerLootEntry {
    itemKey: string;
    count: number;
}

export interface TowerLootGroup {
    category: BagInventoryCategory;
    items: TowerLootEntry[];
}

const RARITY_SORT_WEIGHT: Record<string, number> = {
    [RARITY.LEGENDARY]: 4,
    [RARITY.EPIC]: 3,
    [RARITY.RARE]: 2,
    [RARITY.COMMON]: 1,
};

const CATEGORY_LABEL_FALLBACKS: Record<BagInventoryCategory, { fr: string; en: string }> = {
    combat: { fr: 'Combat', en: 'Combat' },
    permanent: { fr: 'Permanents', en: 'Permanent' },
    held: { fr: 'Objets tenus', en: 'Held items' },
    key: { fr: 'Objets clés', en: 'Key items' },
    evolution_stones: { fr: "Pierres d'évolution", en: 'Evolution stones' },
    berries: { fr: 'Baies', en: 'Berries' },
    ct: { fr: 'CT', en: 'TMs' },
    misc: { fr: 'Divers', en: 'Misc' },
};

const EGG_LOOT_I18N_KEYS: Record<string, string> = {
    [RARITY.COMMON]: 'farmingMetrics.eggCommon',
    [RARITY.RARE]: 'farmingMetrics.eggRare',
    [RARITY.EPIC]: 'farmingMetrics.eggEpic',
    [RARITY.LEGENDARY]: 'farmingMetrics.eggLegendary',
};

export const EGG_RARITY_ORDER_DESC = [
    RARITY.LEGENDARY,
    RARITY.EPIC,
    RARITY.RARE,
    RARITY.COMMON,
] as const;

function raritySortWeight(rarity: string | undefined): number {
    return RARITY_SORT_WEIGHT[rarity || ''] ?? 0;
}

function gameLang(game: GameRuntime): 'fr' | 'en' {
    if (typeof game?.normalizeLanguage === 'function') {
        return game.normalizeLanguage(game.language) === 'en' ? 'en' : 'fr';
    }
    return String(game?.language || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
}

export function bagInventoryCategoryLabel(game: GameRuntime, category: BagInventoryCategory): string {
    const i18nKey = BAG_INVENTORY_CATEGORY_I18N_KEYS[category];
    if (typeof game.t === 'function') {
        const translated = game.t(i18nKey);
        if (translated && translated !== i18nKey) return translated;
    }
    const fb = CATEGORY_LABEL_FALLBACKS[category];
    return gameLang(game) === 'en' ? fb.en : fb.fr;
}

function eggsGroupLabel(game: GameRuntime): string {
    if (typeof game.t === 'function') {
        const key = 'offline.eggsLoot';
        const translated = game.t(key);
        if (translated && translated !== key) return translated;
    }
    return gameLang(game) === 'en' ? 'Eggs' : 'Oeufs';
}

function eggRowLabel(game: GameRuntime, rarity: string): string {
    const eggKey = `egg_${rarity}`;
    const i18nKey = EGG_LOOT_I18N_KEYS[rarity];
    if (i18nKey && typeof game.t === 'function') {
        const translated = game.t(i18nKey);
        if (translated && translated !== i18nKey) return translated;
    }
    if (typeof game.getRarityLabel === 'function') {
        const rarityLabel = game.getRarityLabel(rarity);
        return gameLang(game) === 'en' ? `Egg ${rarityLabel}` : `Oeuf ${rarityLabel}`;
    }
    return eggKey.replace(/_/g, ' ');
}

export function sortEggRaritiesDesc(eggs: Record<string, number>): string[] {
    return EGG_RARITY_ORDER_DESC.filter((rarity) => (eggs[rarity] ?? 0) > 0);
}

export function partitionEggKeysFromLoot(items: Record<string, number>): {
    eggs: Record<string, number>;
    items: Record<string, number>;
} {
    const eggs: Record<string, number> = {};
    const rest: Record<string, number> = {};
    for (const [itemKey, rawCount] of Object.entries(items)) {
        const count = Math.max(0, Math.floor(Number(rawCount) || 0));
        if (count <= 0) continue;
        if (itemKey.startsWith('egg_')) {
            const rarity = itemKey.slice(4);
            eggs[rarity] = (eggs[rarity] || 0) + count;
        } else {
            rest[itemKey] = count;
        }
    }
    return { eggs, items: rest };
}

export function groupTowerLootItems(
    items: Record<string, number>,
    getItemDef: (itemKey: string) => TowerLootItemDef | null | undefined,
    getSortLabel: (itemKey: string, def: TowerLootItemDef | null | undefined) => string,
): TowerLootGroup[] {
    const byCategory = new Map<BagInventoryCategory, TowerLootEntry[]>();

    for (const [itemKey, rawCount] of Object.entries(items)) {
        const count = Math.max(0, Math.floor(Number(rawCount) || 0));
        if (count <= 0) continue;
        const def = getItemDef(itemKey);
        const category = resolveBagItemInventoryCategory(itemKey, def);
        const list = byCategory.get(category) ?? [];
        list.push({ itemKey, count });
        byCategory.set(category, list);
    }

    const groups: TowerLootGroup[] = [];
    for (const category of BAG_INVENTORY_CATEGORY_ORDER) {
        const entries = byCategory.get(category);
        if (!entries || entries.length === 0) continue;
        entries.sort((a, b) => {
            const defA = getItemDef(a.itemKey);
            const defB = getItemDef(b.itemKey);
            const rarityDiff = raritySortWeight(defB?.rarity) - raritySortWeight(defA?.rarity);
            if (rarityDiff !== 0) return rarityDiff;
            const nameA = getSortLabel(a.itemKey, defA).toLowerCase();
            const nameB = getSortLabel(b.itemKey, defB).toLowerCase();
            return nameA.localeCompare(nameB);
        });
        groups.push({ category, items: entries });
    }
    return groups;
}

function renderTowerLootItemRow(
    itemKey: string,
    count: number,
    def: TowerLootItemDef | null | undefined,
    label: string,
    escape: (value: string) => string,
    fmt: (n: number) => string,
): string {
    const icon = def?.icon ?? '';
    const img = def?.img ?? '';
    const iconPath = img || getItemIconPath(itemKey);
    const sprite = iconPath
        ? `<img src="${iconPath}" alt="" class="farming-metrics-top-item-sprite" loading="lazy" decoding="async" onerror="this.style.display='none';this.nextElementSibling&&(this.nextElementSibling.style.display='inline');"><span class="farming-metrics-top-item-icon" style="display:none;">${icon}</span>`
        : (icon ? `<span class="farming-metrics-top-item-icon">${icon}</span>` : '');
    return `<div class="farming-metrics-top-item">${sprite}<span class="farming-metrics-top-item-name">${escape(label)}</span><span class="farming-metrics-top-item-count">x${fmt(count)}</span></div>`;
}

function makeLootLabelHelpers(
    game: GameRuntime,
    allItems: Record<string, TowerLootItemDef>,
): {
    getItemDef: (itemKey: string) => TowerLootItemDef | null | undefined;
    getSortLabel: (itemKey: string, def: TowerLootItemDef | null | undefined) => string;
} {
    const getItemDef = (itemKey: string) => allItems[itemKey] ?? null;
    const getSortLabel = (itemKey: string, def: TowerLootItemDef | null | undefined) => {
        let label = itemKey;
        if (def?.name) {
            label = def.name;
            if (typeof game.getLocalizedItemName === 'function') {
                label = game.getLocalizedItemName(itemKey, label, def);
            }
        }
        return label;
    };
    return { getItemDef, getSortLabel };
}

export function buildTowerEggsGroupsHtml(
    game: GameRuntime,
    eggs: Record<string, number>,
    escape: (value: string) => string,
    fmt: (n: number) => string,
): string {
    const entries = sortEggRaritiesDesc(eggs);
    if (entries.length === 0) return '';

    const itemNodes = entries.map((rarity) => {
        const count = eggs[rarity] ?? 0;
        const eggKey = `egg_${rarity}`;
        const label = eggRowLabel(game, rarity);
        return renderTowerLootItemRow(eggKey, count, null, label, escape, fmt);
    }).join('');

    return `<div class="tower-loot-type-group">`
        + `<div class="farming-metrics-subsection-title">${escape(eggsGroupLabel(game))}</div>`
        + `<div class="farming-metrics-top-items">${itemNodes}</div>`
        + `</div>`;
}

export function buildTowerLootGroupsHtml(
    game: GameRuntime,
    items: Record<string, number>,
    allItems: Record<string, TowerLootItemDef>,
    escape: (value: string) => string,
    fmt: (n: number) => string,
): string {
    const { getItemDef, getSortLabel } = makeLootLabelHelpers(game, allItems);
    const groups = groupTowerLootItems(items, getItemDef, getSortLabel);
    if (groups.length === 0) return '';

    return groups.map((group) => {
        const itemNodes = group.items.map(({ itemKey, count }) => {
            const def = getItemDef(itemKey);
            return renderTowerLootItemRow(itemKey, count, def, getSortLabel(itemKey, def), escape, fmt);
        }).join('');
        return `<div class="tower-loot-type-group">`
            + `<div class="farming-metrics-subsection-title">${escape(bagInventoryCategoryLabel(game, group.category))}</div>`
            + `<div class="farming-metrics-top-items">${itemNodes}</div>`
            + `</div>`;
    }).join('');
}

export function buildTowerLootItemsSectionHtml(
    game: GameRuntime,
    items: Record<string, number>,
    allItems: Record<string, TowerLootItemDef>,
    itemsTitle: string,
    escape: (value: string) => string,
    fmt: (n: number) => string,
): string {
    const groupHtml = buildTowerLootGroupsHtml(game, items, allItems, escape, fmt);
    if (!groupHtml) return '';

    return `<div class="farming-metrics-section">`
        + `<div class="farming-metrics-section-title">${escape(itemsTitle)}</div>`
        + groupHtml
        + `</div>`;
}
