function buildFeticheBerryOverlay(
    berryKey: string,
    taste: FeticheTaste | null,
): { statHint: string | null; statEffect: FeticheBerryStatEffect | null } {
    if (!taste) return { statHint: null, statEffect: null };
    const base = getFeticheBerryStatEffect(berryKey);
    const scaled = scaleFeticheBerryStatEffect(base, FETICHE_TASTE_EFFECTS[taste].statEffMult);
    const hasBase = hasFeticheBerryStatBase(base);
    const hint = formatFeticheBerryStatHint(scaled);
    return { statHint: hasBase ? hint : null, statEffect: hasBase ? scaled : null };
}

function farmT(
    game: GameRuntime,
    key: string,
    fallbackFr: string,
    fallbackEn: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = typeof game?.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : (String(game?.language || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr');
    if (typeof game?.t === 'function') {
        const out = game.t(key, vars);
        if (out && out !== key) return out;
    }
    const template = lang === 'en' ? fallbackEn : fallbackFr;
    return template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));
}

function itemLabel(game: GameRuntime, itemKey: string): string {
    const def = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
    if (typeof game.getLocalizedItemName === 'function') {
        return game.getLocalizedItemName(itemKey, coerceStr(def?.name, itemKey), def);
    }
    return coerceStr(def?.name, itemKey);
}

function itemDescription(game: GameRuntime, itemKey: string): string {
    const def = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
    const fallback = coerceStr(def?.description, '');
    if (typeof game.getLocalizedItemDescription === 'function') {
        return game.getLocalizedItemDescription(itemKey, fallback, def);
    }
    return fallback;
}

function formatGroupedInt(value: number): string {
    const n = Math.max(0, Math.floor(Number(value) || 0));
    return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
}

function queueChecks(
    game: GameRuntime,
    farmLevel: number,
    levelReq: number,
    ownedMilk: number,
    milkReq: number,
): BerryTreeQueueCheckSnapshot {
    return {
        farmMet: farmLevel >= levelReq,
        farmLabel: farmT(
            game,
            'berryTree.queueFarmReq',
            'Ferme niv. {farmLevel} · requis {levelReq}',
            'Farm lv. {farmLevel} · required {levelReq}',
            { farmLevel, levelReq },
        ),
        milkMet: ownedMilk >= milkReq,
        milkLabel: farmT(
            game,
            'berryTree.queueMilkReq',
            'Lait : {milk} (coût : {milkReq})',
            'Milk: {milk} (cost: {milkReq})',
            {
                milk: formatGroupedInt(ownedMilk),
                milkReq: formatGroupedInt(milkReq),
            },
        ),
    };
}

function mulchEffectLabel(game: GameRuntime, mulchKey: string): string {
    const def = BERRY_MULCHES[mulchKey];
    if (!def) return '';
    const time = formatFarmDuration(def.effect.duration, getLang(game));
    if (def.effect.type === 'berryProductionBoost') {
        const mult = Math.max(1, Number(def.effect.mult) || 1);
        const multLabel = (mult % 1 === 0 ? String(mult) : mult.toFixed(1)).replace('.', getLang(game) === 'fr' ? ',' : '.');
        return farmT(
            game,
            'berryTree.mulchEffectSpeed',
            '×{mult} vitesse · {time}',
            '×{mult} speed · {time}',
            { mult: multLabel, time },
        );
    }
    const pct = Math.round(Math.max(0, Math.min(1, Number(def.effect.bonusBerryChance) || 0)) * 100);
    return farmT(
        game,
        'berryTree.mulchEffectBonus',
        '{pct} % de baie bonus · {time}',
        '{pct}% bonus berry · {time}',
        { pct, time },
    );
}

function mulchBlockedLabel(game: GameRuntime, owned: number, hasCrop: boolean): string | null {
    if (owned < 1) {
        return farmT(game, 'berryTree.mulchNoStock', 'Aucun en stock', 'None in stock');
    }
    if (!hasCrop) {
        return farmT(game, 'berryTree.mulchNeedCrop', 'Plante une baie d\'abord', 'Plant a berry first');
    }
    return null;
}

function queueRequirementLabel(
    game: GameRuntime,
    key: string,
    farmLevel: number,
    levelReq: number,
    ownedMilk: number,
    milkReq: number,
): string {
    return farmT(
        game,
        key,
        'Ferme niv. {farmLevel} · requis {levelReq} · Lait : {milk} (coût : {milkReq})',
        'Farm lv. {farmLevel} · required {levelReq} · Milk: {milk} (cost: {milkReq})',
        {
            farmLevel,
            levelReq,
            milk: formatGroupedInt(ownedMilk),
            milkReq: formatGroupedInt(milkReq),
        },
    );
}

function itemIconUrl(itemKey: string | null): string | null {
    if (!itemKey) return null;
    const item = ALL_ITEMS[itemKey as keyof typeof ALL_ITEMS] as { img?: string } | undefined;
    return item?.img ?? null;
}

function hasBerryPlantIngredients(
    berryKey: string,
    items: Readonly<Record<string, number>>,
): boolean {
    const recipe = getBerryTreeRecipe(berryKey);
    if (!recipe) return false;
    return recipe.ingredients.every(
        (ing) => Math.max(0, Math.floor(Number(items[ing]) || 0)) >= 1,
    );
}

