/** HGSS-style overworld guardian sprites (veekun → img/guardian-overworld/). */

import { GUARDIAN_OVERWORLD_MANIFEST } from '../../constants/guardianOverworldManifest.ts';
import type { MiltankOwDir } from './miltankOverworldSprites.ts';

export function hasGuardianOverworldSprites(species: string | null | undefined): boolean {
    if (!species) return false;
    return Object.prototype.hasOwnProperty.call(GUARDIAN_OVERWORLD_MANIFEST, species);
}

export function guardianOverworldSpritePath(
    species: string,
    dir: MiltankOwDir,
    frame: 1 | 2,
    shiny: boolean,
): string {
    const tier = shiny ? 'shiny' : 'normal';
    return `img/guardian-overworld/${species}/${tier}/${dir}-${frame}.png`;
}

function toCssUrl(path: string): string {
    if (typeof document !== 'undefined' && document.baseURI && /^https?:/i.test(document.baseURI)) {
        try {
            return `url('${new URL(path, document.baseURI).href}')`;
        } catch {
            // fallback if URL construction fails
        }
    }
    return `url('${path}')`;
}

export function guardianOverworldCssVars(species: string, shiny: boolean): Record<string, string> {
    const dirs: MiltankOwDir[] = ['down', 'up', 'left', 'right'];
    const vars: Record<string, string> = {};
    for (const dir of dirs) {
        vars[`--go-${dir}-1`] = toCssUrl(guardianOverworldSpritePath(species, dir, 1, shiny));
        vars[`--go-${dir}-2`] = toCssUrl(guardianOverworldSpritePath(species, dir, 2, shiny));
    }
    return vars;
}

export function guardianOverworldStyleString(species: string, shiny: boolean): string {
    return Object.entries(guardianOverworldCssVars(species, shiny))
        .map(([key, value]) => `${key}: ${value}`)
        .join('; ');
}
