/**
 * @file src/lib/berryTreeLogic.ts
 * Pure berry tree discovery / production logic (Vitest-friendly).
 */

import { isUnknownArray } from './safeAccess.ts';
import {
    BERRY_TREE,
    BERRY_TREE_RECIPES,
    BERRY_MULCHES,
    BERRY_DEX_KEYS,
    BERRY_TREE_SESSION_STOCK_CAP,
    BERRY_PRODUCTION_TIME_REDUCTION_CAP,
    getBerryBerriesPerHour,
    getBerryTreeRecipe,
    isBerryCombineEligibleItemKey,
} from '../../constants/balance/berryTree.ts';

export interface BerryTreeCropState {
    berryKey: string;
    storedQty: number;
    pendingFraction: number;
    stockCap: number;
    /** Fractional accumulator for bonus-berry procs (Damp mulch). */
    bonusBerryFraction: number;
    /** True when stock reached cap — no further production until claim ends session. */
    productionComplete: boolean;
}

export interface BerryPendingCombine {
    /** Ordered slot contents (empty string = unfilled slot). */
    submitted: string[];
    startedAt: number;
    completesAt: number;
}

export interface BerryCombineQueueEntry {
    submitted: string[];
}

export interface BerryTreeState {
    unlockedBerryKeys: string[];
    revealedSlotsByBerry: Record<string, (string | null)[]>;
    activeCrop: BerryTreeCropState | null;
    productionBoostMult: number;
    productionBoostUntil: number;
    yieldBoostMult: number;
    /** Chance of +1 bonus berry per berry produced while mulch active (Damp). */
    bonusBerryChance: number;
    /** Active discovery combine awaiting results. */
    pendingCombine: BerryPendingCombine | null;
    /** Queued submissions when combine queue upgrade is purchased. */
    combineQueue: BerryCombineQueueEntry[];
    /** Analysis queue upgrade level (0..combineQueueMaxLevels). */
    combineQueueLevel: number;
    /** Draft slots for discovery combiner UI (ordered). */
    combineDraft: (string | null)[];
    /** Berries queued to plant when the tree is free (max length = plantQueueLevel). */
    plantQueue: string[];
    /** Plant queue upgrade level (0..plantQueueMaxLevels). */
    plantQueueLevel: number;
    /** Recent combine attempts (up to BERRY_COMBINE_HISTORY_LIMIT). */
    combineHistory: BerryCombineHistoryEntry[];
    /** Result of the most recent completed analysis for display. */
    lastCombineResult: BerryCombineHistoryEntry | null;
    /** All serialized 3-slot combinations ever attempted ("itemA|itemB|itemC"). */
    attemptedCombinations: string[];
    /** Attempts that matched no recipe and revealed no hint. */
    failedCombinations: string[];
}

export interface BerrySlotReveal {
    berryKey: string;
    slotIndex: number;
    itemKey: string;
}

export interface BerryCombineHistoryEntry {
    submitted: string[];
    timestamp: number;
    newlyRevealed: BerrySlotReveal[];
    newlyUnlocked: string[];
    success: boolean;
}

export interface ApplySlotRevealsResult {
    newlyRevealed: BerrySlotReveal[];
    newlyUnlocked: string[];
}

/** How many completed analyses stay in the journal and in the save. */
export const BERRY_COMBINE_HISTORY_LIMIT = 5;

export interface TryBerryCombinationResult extends ApplySlotRevealsResult {
    ok: boolean;
    error?: 'empty' | 'invalid_item' | 'missing_items' | 'in_progress' | 'queue_full';
    consumedItems: string[];
    queued?: boolean;
}

export function createDefaultBerryTreeState(): BerryTreeState {
    return {
        unlockedBerryKeys: [],
        revealedSlotsByBerry: {},
        activeCrop: null,
        productionBoostMult: 1,
        productionBoostUntil: 0,
        yieldBoostMult: 1,
        bonusBerryChance: 0,
        pendingCombine: null,
        combineQueue: [],
        combineQueueLevel: 0,
        combineDraft: [null, null, null],
        plantQueue: [],
        plantQueueLevel: 0,
        combineHistory: [],
        lastCombineResult: null,
        attemptedCombinations: [],
        failedCombinations: [],
    };
}

function clampQueueLevel(level: number, maxLevels: number): number {
    return Math.max(0, Math.min(maxLevels, Math.floor(Number(level) || 0)));
}

export function getBerryQueueUpgradeCost(
    baseCost: Readonly<{ moomoo_milk: number; minFarmLevel: number }>,
    nextLevel: number,
): { moomoo_milk: number; minFarmLevel: number } {
    const tier = Math.max(1, Math.floor(nextLevel));
    return {
        minFarmLevel: baseCost.minFarmLevel + (tier - 1),
        moomoo_milk: baseCost.moomoo_milk + (tier - 1),
    };
}

export function getCombineQueueUpgradeCostForNextLevel(state: BerryTreeState): {
    moomoo_milk: number;
    minFarmLevel: number;
} {
    return getBerryQueueUpgradeCost(
        BERRY_TREE.combineQueueUpgradeBaseCost,
        state.combineQueueLevel + 1,
    );
}

export function getPlantQueueUpgradeCostForNextLevel(state: BerryTreeState): {
    moomoo_milk: number;
    minFarmLevel: number;
} {
    return getBerryQueueUpgradeCost(
        BERRY_TREE.plantQueueUpgradeBaseCost,
        state.plantQueueLevel + 1,
    );
}

export function hasCombineQueueUpgrade(state: BerryTreeState): boolean {
    return state.combineQueueLevel > 0;
}

export function getMaxPlantQueueSize(state: BerryTreeState): number {
    return Math.max(0, state.plantQueueLevel);
}

function normalizePlantQueue(
    raw: unknown,
    legacyBerryKey: unknown,
    unlockedBerryKeys: readonly string[],
    maxSize: number,
): string[] {
    const out: string[] = [];
    const pushKey = (key: string) => {
        if (!key || !unlockedBerryKeys.includes(key)) return;
        out.push(key);
    };
    if (Array.isArray(raw)) {
        for (const entry of raw) {
            if (typeof entry !== 'string') continue;
            pushKey(entry.trim());
            if (out.length >= maxSize) break;
        }
    } else if (typeof legacyBerryKey === 'string') {
        pushKey(legacyBerryKey.trim());
    }
    return out.slice(0, maxSize);
}

function normalizePendingCombine(raw: unknown): BerryPendingCombine | null {
    if (!raw || typeof raw !== 'object') return null;
    const obj = raw as Record<string, unknown>;
    const submitted = Array.isArray(obj.submitted)
        ? obj.submitted.map((s) => (typeof s === 'string' ? s : '')).slice(0, BERRY_TREE.combineSlotCount)
        : [];
    while (submitted.length < BERRY_TREE.combineSlotCount) submitted.push('');
    const startedAt = Math.max(0, Number(obj.startedAt) || 0);
    const completesAt = Math.max(0, Number(obj.completesAt) || 0);
    if (!Number.isFinite(startedAt) || !Number.isFinite(completesAt)) return null;
    if (startedAt <= 0 || completesAt <= startedAt) return null;
    if (!submitted.some((s) => s.length > 0)) return null;
    return { submitted, startedAt, completesAt };
}

function ensureRevealedSlotsForBerry(state: BerryTreeState, berryKey: string): (string | null)[] {
    if (!state.revealedSlotsByBerry[berryKey]) {
        const recipe = getBerryTreeRecipe(berryKey);
        const len = recipe?.ingredients.length ?? 0;
        state.revealedSlotsByBerry[berryKey] = Array.from({ length: len }, () => null);
    }
    return state.revealedSlotsByBerry[berryKey];
}

export function normalizeBerryTreeState(state: BerryTreeState | null | undefined): BerryTreeState {
    const base = state && typeof state === 'object' ? state : createDefaultBerryTreeState();
    const unlockedBerryKeys = Array.isArray(base.unlockedBerryKeys)
        ? [...new Set(base.unlockedBerryKeys.filter((k) => typeof k === 'string' && BERRY_DEX_KEYS.includes(k as typeof BERRY_DEX_KEYS[number])))]
        : [];
    const revealedSlotsByBerry: Record<string, (string | null)[]> = {};
    for (const berryKey of BERRY_DEX_KEYS) {
        const recipe = getBerryTreeRecipe(berryKey);
        if (!recipe) continue;
        const existing = base.revealedSlotsByBerry?.[berryKey];
        const slots: (string | null)[] = recipe.ingredients.map((ingredient, i) => {
            const raw = Array.isArray(existing) ? existing[i] : null;
            return raw === ingredient ? ingredient : null;
        });
        revealedSlotsByBerry[berryKey] = slots;
    }
    let activeCrop: BerryTreeCropState | null = null;
    if (base.activeCrop && typeof base.activeCrop === 'object') {
        const berryKey = String(base.activeCrop.berryKey ?? '');
        if (unlockedBerryKeys.includes(berryKey)) {
            const stockCap = BERRY_TREE_SESSION_STOCK_CAP;
            const storedQty = Math.min(
                stockCap,
                Math.max(0, Math.floor(Number(base.activeCrop.storedQty) || 0)),
            );
            activeCrop = {
                berryKey,
                storedQty,
                pendingFraction: Math.max(0, Number(base.activeCrop.pendingFraction) || 0),
                stockCap,
                bonusBerryFraction: Math.max(0, Number(base.activeCrop.bonusBerryFraction) || 0),
                productionComplete: !!base.activeCrop.productionComplete || storedQty >= stockCap,
            };
        }
    }
    let combineQueueLevel = clampQueueLevel(
        Number((base as { combineQueueLevel?: unknown }).combineQueueLevel),
        BERRY_TREE.combineQueueMaxLevels,
    );
    if (combineQueueLevel <= 0 && !!(base as { combineQueueUpgradePurchased?: unknown }).combineQueueUpgradePurchased) {
        combineQueueLevel = Math.min(BERRY_TREE.combineQueueMaxLevels, 3);
    }
    let plantQueueLevel = clampQueueLevel(
        Number((base as { plantQueueLevel?: unknown }).plantQueueLevel),
        BERRY_TREE.plantQueueMaxLevels,
    );
    if (plantQueueLevel <= 0 && !!(base as { plantQueueUnlocked?: unknown }).plantQueueUnlocked) {
        plantQueueLevel = 1;
    }
    const plantQueue = normalizePlantQueue(
        (base as { plantQueue?: unknown }).plantQueue,
        (base as { plantQueueBerryKey?: unknown }).plantQueueBerryKey,
        unlockedBerryKeys,
        plantQueueLevel,
    );
    const rawHistory = Array.isArray((base as { combineHistory?: unknown }).combineHistory)
        ? (base as { combineHistory: unknown[] }).combineHistory
        : [];
    const combineHistory: BerryCombineHistoryEntry[] = rawHistory
        .map(normalizeCombineHistoryEntry)
        .filter((h): h is BerryCombineHistoryEntry => h !== null)
        .slice(0, BERRY_COMBINE_HISTORY_LIMIT);
    const rawLastResult = (base as { lastCombineResult?: unknown }).lastCombineResult;
    const lastCombineResult = rawLastResult === undefined
        ? (combineHistory[0] ?? null)
        : (rawLastResult ? normalizeCombineHistoryEntry(rawLastResult) : null);
    const rawAttempted = Array.isArray((base as { attemptedCombinations?: unknown }).attemptedCombinations)
        ? (base as { attemptedCombinations: unknown[] }).attemptedCombinations
        : [];
    const attemptedCombinations: string[] = [
        ...new Set(rawAttempted.filter((k): k is string => typeof k === 'string' && k.length > 0)),
    ];
    for (const h of combineHistory) {
        const key = h.submitted.join('|');
        if (key && !attemptedCombinations.includes(key)) attemptedCombinations.push(key);
    }
    const rawFailed = Array.isArray((base as { failedCombinations?: unknown }).failedCombinations)
        ? (base as { failedCombinations: unknown[] }).failedCombinations
        : [];
    const failedCombinations: string[] = [
        ...new Set(rawFailed.filter((k): k is string => typeof k === 'string' && k.length > 0)),
    ];
    for (const h of combineHistory) {
        const key = h.submitted.join('|');
        if (!key) continue;
        if (h.success) {
            const idx = failedCombinations.indexOf(key);
            if (idx >= 0) failedCombinations.splice(idx, 1);
        } else if (!failedCombinations.includes(key)) {
            failedCombinations.push(key);
        }
    }
    return {
        unlockedBerryKeys,
        revealedSlotsByBerry,
        activeCrop,
        productionBoostMult: Math.max(1, Number(base.productionBoostMult) || 1),
        productionBoostUntil: Math.max(0, Number(base.productionBoostUntil) || 0),
        yieldBoostMult: Math.max(1, Number(base.yieldBoostMult) || 1),
        bonusBerryChance: Math.max(0, Math.min(1, Number(base.bonusBerryChance) || 0)),
        pendingCombine: normalizePendingCombine(base.pendingCombine),
        combineQueue: normalizeCombineQueue(base.combineQueue).slice(0, BERRY_TREE.combineQueueMaxLevels),
        combineQueueLevel,
        combineDraft: normalizeCombineDraft(base.combineDraft),
        plantQueue,
        plantQueueLevel,
        combineHistory,
        lastCombineResult,
        attemptedCombinations,
        failedCombinations,
    };
}

function normalizeCombineHistoryEntry(raw: unknown): BerryCombineHistoryEntry | null {
    if (!raw || typeof raw !== 'object') return null;
    const obj = raw as Record<string, unknown>;
    const submitted = Array.isArray(obj.submitted)
        ? obj.submitted.map((s) => (typeof s === 'string' ? s.trim() : '')).slice(0, BERRY_TREE.combineSlotCount)
        : [];
    while (submitted.length < BERRY_TREE.combineSlotCount) submitted.push('');
    if (!submitted.some((s) => s.length > 0)) return null;
    const timestamp = Math.max(0, Number(obj.timestamp) || 0);
    const newlyUnlocked = Array.isArray(obj.newlyUnlocked)
        ? obj.newlyUnlocked.filter((k): k is string => typeof k === 'string')
        : [];
    const newlyRevealed = Array.isArray(obj.newlyRevealed)
        ? obj.newlyRevealed
            .map((r) => {
                const row = r as Record<string, unknown>;
                return {
                    berryKey: typeof row.berryKey === 'string' ? row.berryKey : '',
                    slotIndex: Math.max(0, Math.floor(Number(row.slotIndex) || 0)),
                    itemKey: typeof row.itemKey === 'string' ? row.itemKey : '',
                };
            })
            .filter((r) => r.berryKey.length > 0 && r.itemKey.length > 0)
        : [];
    const success = obj.success === true || newlyUnlocked.length > 0 || newlyRevealed.length > 0;
    return {
        submitted,
        timestamp,
        newlyRevealed,
        newlyUnlocked,
        success,
    };
}

function normalizeCombineQueue(raw: unknown): BerryCombineQueueEntry[] {
    if (!Array.isArray(raw)) return [];
    const out: BerryCombineQueueEntry[] = [];
    for (const entry of raw) {
        if (!entry || typeof entry !== 'object') continue;
        const submitted = Array.isArray((entry as BerryCombineQueueEntry).submitted)
            ? (entry as BerryCombineQueueEntry).submitted.map((s) => (typeof s === 'string' ? s : '')).slice(0, BERRY_TREE.combineSlotCount)
            : [];
        while (submitted.length < BERRY_TREE.combineSlotCount) submitted.push('');
        if (!submitted.some((s) => s.length > 0)) continue;
        out.push({ submitted });
    }
    return out;
}

function normalizeCombineDraft(raw: unknown): (string | null)[] {
    const slots: (string | null)[] = [null, null, null];
    if (!isUnknownArray(raw)) return slots;
    for (let i = 0; i < BERRY_TREE.combineSlotCount; i++) {
        const v = raw[i];
        slots[i] = typeof v === 'string' && v.length > 0 ? v : null;
    }
    return slots;
}

function trimSubmitted(submitted: readonly string[]): string[] {
    const trimmed = submitted.map((s) => (typeof s === 'string' ? s.trim() : '')).slice(0, BERRY_TREE.combineSlotCount);
    while (trimmed.length < BERRY_TREE.combineSlotCount) trimmed.push('');
    return trimmed;
}

export function getMaxCombineInFlight(state: BerryTreeState): number {
    return BERRY_TREE.combineQueueMaxBase + Math.max(0, state.combineQueueLevel);
}

export function getCombineInFlightCount(state: BerryTreeState, now: number): number {
    const active = isBerryCombineInProgress(state, now) ? 1 : 0;
    return active + (state.combineQueue?.length ?? 0);
}

function startPendingCombine(state: BerryTreeState, submitted: string[], now: number): void {
    state.pendingCombine = {
        submitted,
        startedAt: now,
        completesAt: now + BERRY_TREE.combineCooldownMs,
    };
}

function promoteNextQueuedCombine(state: BerryTreeState, now: number): boolean {
    const next = state.combineQueue.shift();
    if (!next) return false;
    startPendingCombine(state, trimSubmitted(next.submitted), now);
    return true;
}

export function setBerryCombineDraftSlot(
    state: BerryTreeState,
    slotIndex: number,
    itemKey: string | null,
): boolean {
    if (state.pendingCombine && !hasCombineQueueUpgrade(state)) return false;
    if (slotIndex < 0 || slotIndex >= BERRY_TREE.combineSlotCount) return false;
    state.combineDraft[slotIndex] = itemKey && itemKey.length > 0 ? itemKey : null;
    return true;
}

export function clearBerryCombineDraft(state: BerryTreeState): boolean {
    if (state.pendingCombine && !hasCombineQueueUpgrade(state)) return false;
    state.combineDraft = [null, null, null];
    return true;
}

export function isBerryUnlocked(state: BerryTreeState, berryKey: string): boolean {
    return state.unlockedBerryKeys.includes(berryKey);
}

function allSlotsRevealed(state: BerryTreeState, berryKey: string): boolean {
    const slots = ensureRevealedSlotsForBerry(state, berryKey);
    const recipe = getBerryTreeRecipe(berryKey);
    if (!recipe) return false;
    return recipe.ingredients.every((ingredient, i) => slots[i] === ingredient);
}

export function applySlotReveals(
    state: BerryTreeState,
    submitted: readonly string[],
): ApplySlotRevealsResult {
    const newlyRevealed: BerrySlotReveal[] = [];
    const newlyUnlocked: string[] = [];

    for (const recipe of BERRY_TREE_RECIPES) {
        const slots = ensureRevealedSlotsForBerry(state, recipe.berryKey);
        for (let i = 0; i < recipe.ingredients.length; i++) {
            const submittedItem = submitted[i];
            const ingredient = recipe.ingredients[i];
            if (!submittedItem || ingredient === undefined) continue;
            if (submittedItem !== ingredient) continue;
            if (slots[i] === ingredient) continue;
            slots[i] = ingredient;
            newlyRevealed.push({ berryKey: recipe.berryKey, slotIndex: i, itemKey: submittedItem });
        }
        if (allSlotsRevealed(state, recipe.berryKey) && !isBerryUnlocked(state, recipe.berryKey)) {
            state.unlockedBerryKeys.push(recipe.berryKey);
            newlyUnlocked.push(recipe.berryKey);
        }
    }

    return { newlyRevealed, newlyUnlocked };
}

export function getBerryProductionMult(state: BerryTreeState, now: number): number {
    const until = Math.max(0, Number(state.productionBoostUntil) || 0);
    if (until <= now) return 1;
    return Math.max(1, Number(state.productionBoostMult) || 1);
}

export function getBerryYieldMult(state: BerryTreeState, now: number): number {
    const until = Math.max(0, Number(state.productionBoostUntil) || 0);
    if (until <= now) return 1;
    return Math.max(1, Number(state.yieldBoostMult) || 1);
}

export function getBerryBonusBerryChance(state: BerryTreeState, now: number): number {
    const until = Math.max(0, Number(state.productionBoostUntil) || 0);
    if (until <= now) return 0;
    return Math.max(0, Math.min(1, Number(state.bonusBerryChance) || 0));
}

export function computeBerryBerriesPerHour(
    state: BerryTreeState,
    now: number,
    opts?: { productionTimeReduction?: number },
): number {
    const crop = state.activeCrop;
    if (!crop?.berryKey) return 0;
    const base = getBerryBerriesPerHour(crop.berryKey);
    const reduction = Math.max(0, Math.min(BERRY_PRODUCTION_TIME_REDUCTION_CAP, Number(opts?.productionTimeReduction) || 0));
    const timeMult = reduction > 0 ? 1 / (1 - reduction) : 1;
    return base * getBerryProductionMult(state, now) * timeMult;
}

function tickBerryCrop(
    crop: BerryTreeCropState,
    berriesPerHour: number,
    hours: number,
    yieldMult: number,
    bonusBerryChance: number,
): void {
    const rawRate = Number(berriesPerHour);
    const rate = Number.isFinite(rawRate) && rawRate > 0 ? rawRate : 0;
    const rawHours = Number(hours);
    const safeHours = Number.isFinite(rawHours) && rawHours > 0 ? rawHours : 0;
    const rawYield = Number(yieldMult);
    const safeYield = Number.isFinite(rawYield) && rawYield > 0 ? rawYield : 1;
    const produced = rate * safeHours * safeYield;
    const safeProduced = Number.isFinite(produced) && produced > 0 ? produced : 0;
    let pending = (Number(crop.pendingFraction) || 0) + safeProduced;
    if (!Number.isFinite(pending)) pending = 0;
    let stored = Math.max(0, Math.floor(Number(crop.storedQty) || 0));
    const cap = Math.max(1, Math.floor(Number(crop.stockCap) || 1));
    const room = Math.max(0, cap - stored);
    const whole = Math.min(room, Math.floor(pending));
    pending -= whole;
    stored += whole;

    const safeBonusChance = Number.isFinite(bonusBerryChance) ? Math.max(0, bonusBerryChance) : 0;
    if (safeBonusChance > 0 && whole > 0) {
        let bonusFraction = (Number(crop.bonusBerryFraction) || 0) + whole * safeBonusChance;
        if (!Number.isFinite(bonusFraction)) bonusFraction = 0;
        let bonusWhole = Math.floor(bonusFraction);
        bonusFraction -= bonusWhole;
        const bonusRoom = Math.max(0, cap - stored);
        bonusWhole = Math.min(bonusRoom, bonusWhole);
        stored += bonusWhole;
        crop.bonusBerryFraction = bonusFraction;
    }

    if (stored >= cap) {
        pending = Math.min(pending, 0.999);
        crop.productionComplete = true;
    }
    crop.pendingFraction = pending;
    crop.storedQty = stored;
    crop.stockCap = cap;
}

export function tickBerryTreeState(
    state: BerryTreeState,
    elapsedMs: number,
    now: number,
    opts?: { productionTimeReduction?: number },
): void {
    const crop = state.activeCrop;
    if (!crop?.berryKey || crop.productionComplete) return;
    if (!Number.isFinite(elapsedMs) || elapsedMs <= 0) return;
    const safeNow = Number.isFinite(now) ? now : Date.now();
    const hours = elapsedMs / (60 * 60 * 1000);
    const rate = computeBerryBerriesPerHour(state, safeNow, opts);
    const yieldMult = getBerryYieldMult(state, safeNow);
    const bonusBerryChance = getBerryBonusBerryChance(state, safeNow);
    tickBerryCrop(crop, rate, hours, yieldMult, bonusBerryChance);
}

export function isBerryCombineInProgress(state: BerryTreeState, now: number): boolean {
    const pending = state.pendingCombine;
    if (!pending) return false;
    return now < pending.completesAt;
}

export function getBerryCombineProgress(state: BerryTreeState, now: number): {
    inProgress: boolean;
    progressPct: number;
    remainingMs: number;
} {
    const pending = state?.pendingCombine;
    if (!pending || !Number.isFinite(now) || now >= pending.completesAt) {
        return { inProgress: false, progressPct: 0, remainingMs: 0 };
    }
    const totalMs = Math.max(1, pending.completesAt - pending.startedAt);
    const elapsedMs = Math.max(0, now - pending.startedAt);
    const progressPct = Math.min(100, Math.max(0, Math.round((elapsedMs / totalMs) * 100)));
    return {
        inProgress: true,
        progressPct,
        remainingMs: Math.max(0, pending.completesAt - now),
    };
}

/** @deprecated use getBerryCombineProgress */
export function getBerryCombineCooldownRemainingMs(state: BerryTreeState, now: number): number {
    return getBerryCombineProgress(state, now).remainingMs;
}

/** @deprecated use isBerryCombineInProgress */
export function isBerryCombineOnCooldown(state: BerryTreeState, now: number): boolean {
    return isBerryCombineInProgress(state, now);
}

export function resolveBerryPendingCombineIfReady(
    state: BerryTreeState,
    now: number,
): TryBerryCombinationResult | null {
    if (!state || typeof state !== 'object') return null;
    if (!Number.isFinite(now) || now < 0) return null;
    const pending = state.pendingCombine;
    if (!pending || !Number.isFinite(pending.completesAt) || now < pending.completesAt) return null;
    state.pendingCombine = null;
    const revealResult = applySlotReveals(state, pending.submitted);
    promoteNextQueuedCombine(state, now);

    const success = revealResult.newlyRevealed.length > 0 || revealResult.newlyUnlocked.length > 0;
    const historyEntry: BerryCombineHistoryEntry = {
        submitted: [...pending.submitted],
        timestamp: now,
        newlyRevealed: revealResult.newlyRevealed,
        newlyUnlocked: revealResult.newlyUnlocked,
        success,
    };
    if (!state.combineHistory) state.combineHistory = [];
    state.combineHistory.unshift(historyEntry);
    if (state.combineHistory.length > BERRY_COMBINE_HISTORY_LIMIT) {
        state.combineHistory.length = BERRY_COMBINE_HISTORY_LIMIT;
    }
    state.lastCombineResult = historyEntry;

    if (!state.attemptedCombinations) state.attemptedCombinations = [];
    const attemptKey = pending.submitted.join('|');
    if (!state.attemptedCombinations.includes(attemptKey)) {
        state.attemptedCombinations.push(attemptKey);
    }
    if (!state.failedCombinations) state.failedCombinations = [];
    if (!success) {
        if (attemptKey && !state.failedCombinations.includes(attemptKey)) {
            state.failedCombinations.push(attemptKey);
        }
    } else {
        state.failedCombinations = state.failedCombinations.filter((key) => key !== attemptKey);
    }

    return { ok: true, consumedItems: [], ...revealResult };
}

export function isCombineDraftAlreadyAttempted(
    state: BerryTreeState,
    submitted: readonly (string | null | undefined)[],
): boolean {
    if (!submitted || submitted.length < BERRY_TREE.combineSlotCount) return false;
    const filled = submitted.filter((s): s is string => typeof s === 'string' && s.trim().length > 0);
    if (filled.length < BERRY_TREE.combineSlotCount) return false;
    const key = submitted.map((s) => (s ? s.trim() : '')).join('|');
    if (state.attemptedCombinations?.includes(key)) return true;
    if (state.combineHistory?.some((h) => h.submitted.join('|') === key)) return true;
    return false;
}

export function dismissBerryLastCombineResult(state: BerryTreeState): void {
    state.lastCombineResult = null;
}

function validateBerryCombineSubmission(
    submitted: readonly string[],
    ownedItems: Readonly<Record<string, number>>,
): TryBerryCombinationResult | null {
    const trimmed = submitted.map((s) => (typeof s === 'string' ? s.trim() : '')).slice(0, BERRY_TREE.combineSlotCount);
    const filled = trimmed.filter((s) => s.length > 0);
    if (filled.length === 0) {
        return { ok: false, error: 'empty', consumedItems: [], newlyRevealed: [], newlyUnlocked: [] };
    }
    const neededByKey = new Map<string, number>();
    for (const itemKey of filled) {
        if (!isBerryCombineEligibleItemKey(itemKey)) {
            return { ok: false, error: 'invalid_item', consumedItems: [], newlyRevealed: [], newlyUnlocked: [] };
        }
        neededByKey.set(itemKey, (neededByKey.get(itemKey) ?? 0) + 1);
    }
    const safeOwned = (ownedItems && typeof ownedItems === 'object') ? ownedItems : {};
    for (const [itemKey, qty] of neededByKey) {
        if ((Number(safeOwned[itemKey]) || 0) < qty) {
            return { ok: false, error: 'missing_items', consumedItems: [], newlyRevealed: [], newlyUnlocked: [] };
        }
    }
    return null;
}

/** True when every filled slot is eligible and bag counts cover duplicate uses across slots. */
export function canAffordBerryCombineSubmission(
    submitted: readonly (string | null)[],
    ownedItems: Readonly<Record<string, number>>,
): boolean {
    return validateBerryCombineSubmission(
        submitted.map((s) => s ?? ''),
        ownedItems,
    ) === null;
}

export function beginBerryCombination(
    state: BerryTreeState,
    submitted: readonly string[],
    ownedItems: Readonly<Record<string, number>>,
    now = Date.now(),
): TryBerryCombinationResult {
    resolveBerryPendingCombineIfReady(state, now);
    const trimmed = trimSubmitted(submitted);
    const validationError = validateBerryCombineSubmission(trimmed, ownedItems);
    if (validationError) return validationError;

    const filled = trimmed.filter((s) => s.length > 0);
    const inFlight = getCombineInFlightCount(state, now);
    const maxInFlight = getMaxCombineInFlight(state);

    if (isBerryCombineInProgress(state, now)) {
        if (!hasCombineQueueUpgrade(state)) {
            return { ok: false, error: 'in_progress', consumedItems: [], newlyRevealed: [], newlyUnlocked: [] };
        }
        if (inFlight >= maxInFlight) {
            return { ok: false, error: 'queue_full', consumedItems: [], newlyRevealed: [], newlyUnlocked: [] };
        }
        state.combineDraft = [null, null, null];
        state.combineQueue.push({ submitted: trimmed });
        return { ok: true, consumedItems: [...filled], newlyRevealed: [], newlyUnlocked: [], queued: true };
    }

    if (inFlight >= maxInFlight) {
        return { ok: false, error: 'queue_full', consumedItems: [], newlyRevealed: [], newlyUnlocked: [] };
    }

    state.combineDraft = [null, null, null];
    startPendingCombine(state, trimmed, now);
    return { ok: true, consumedItems: [...filled], newlyRevealed: [], newlyUnlocked: [] };
}

/** Immediate combine (tests / legacy). Prefer begin + resolve for gameplay. */
export function tryBerryCombination(
    state: BerryTreeState,
    submitted: readonly string[],
    ownedItems: Readonly<Record<string, number>>,
    now = Date.now(),
): TryBerryCombinationResult {
    const begin = beginBerryCombination(state, submitted, ownedItems, now);
    if (!begin.ok) return begin;
    const resolved = resolveBerryPendingCombineIfReady(state, now + BERRY_TREE.combineCooldownMs);
    if (resolved) {
        return { ...resolved, consumedItems: begin.consumedItems };
    }
    return { ok: true, consumedItems: begin.consumedItems, newlyRevealed: [], newlyUnlocked: [] };
}

export function purchaseBerryCombineQueueUpgrade(state: BerryTreeState): boolean {
    if (!state || typeof state !== 'object') return false;
    if (state.combineQueueLevel >= BERRY_TREE.combineQueueMaxLevels) return false;
    state.combineQueueLevel += 1;
    return true;
}

export function canPurchaseBerryCombineQueueUpgrade(
    state: BerryTreeState,
    ownedMoomooMilk: number,
    farmLevel: number,
): boolean {
    if (!state || typeof state !== 'object') return false;
    if (state.combineQueueLevel >= BERRY_TREE.combineQueueMaxLevels) return false;
    const cost = getCombineQueueUpgradeCostForNextLevel(state);
    return Number.isFinite(farmLevel)
        && farmLevel >= cost.minFarmLevel
        && Number.isFinite(ownedMoomooMilk)
        && ownedMoomooMilk >= cost.moomoo_milk;
}

export function plantBerryCrop(state: BerryTreeState, berryKey: string): boolean {
    if (!isBerryUnlocked(state, berryKey)) return false;
    state.activeCrop = {
        berryKey,
        storedQty: 0,
        pendingFraction: 0,
        stockCap: BERRY_TREE_SESSION_STOCK_CAP,
        bonusBerryFraction: 0,
        productionComplete: false,
    };
    return true;
}

export function getBerryPlantIngredientKeys(berryKey: string): string[] {
    const ingredients = getBerryTreeRecipe(berryKey)?.ingredients;
    return ingredients ? [...ingredients] : [];
}

export function canAffordBerryPlant(
    state: BerryTreeState,
    berryKey: string,
    ownedItems: Readonly<Record<string, number>>,
): { ok: boolean; error?: 'not_unlocked' | 'missing_items'; ingredients: string[] } {
    if (!isBerryUnlocked(state, berryKey)) {
        return { ok: false, error: 'not_unlocked', ingredients: [] };
    }
    const ingredients = getBerryPlantIngredientKeys(berryKey);
    if (ingredients.length === 0) {
        return { ok: false, error: 'not_unlocked', ingredients: [] };
    }
    const safeOwned = (ownedItems && typeof ownedItems === 'object') ? ownedItems : {};
    for (const itemKey of ingredients) {
        if ((Number(safeOwned[itemKey]) || 0) < 1) {
            return { ok: false, error: 'missing_items', ingredients };
        }
    }
    return { ok: true, ingredients };
}

function extendMulchDuration(state: BerryTreeState, duration: number, now: number): void {
    const currentUntil = Math.max(0, Number(state.productionBoostUntil) || 0);
    const base = currentUntil > now ? currentUntil : now;
    state.productionBoostUntil = base + duration;
}

export function applyBerryFertilizer(state: BerryTreeState, mulchKey: string, now: number): boolean {
    const def = BERRY_MULCHES[mulchKey];
    if (!def?.effect) return false;

    if (def.effect.type === 'berryProductionBoost') {
        const duration = Math.max(0, Number(def.effect.duration) || 0);
        const mult = Math.max(1, Number(def.effect.mult) || 1);
        const yieldMult = Math.max(1, Number(def.effect.yieldMult) || 1);
        if (duration <= 0) return false;
        extendMulchDuration(state, duration, now);
        state.productionBoostMult = mult;
        state.yieldBoostMult = yieldMult;
        state.bonusBerryChance = 0;
        return true;
    }

    if (def.effect.type === 'berryBonusChance') {
        const duration = Math.max(0, Number(def.effect.duration) || 0);
        const bonusBerryChance = Math.max(0, Math.min(1, Number(def.effect.bonusBerryChance) || 0));
        if (duration <= 0 || bonusBerryChance <= 0) return false;
        extendMulchDuration(state, duration, now);
        state.productionBoostMult = 1;
        state.yieldBoostMult = 1;
        state.bonusBerryChance = bonusBerryChance;
        return true;
    }

    return false;
}

export function isBerryCropSessionComplete(crop: BerryTreeCropState): boolean {
    const cap = Math.max(1, Math.floor(Number(crop.stockCap) || 1));
    const stored = Math.max(0, Math.floor(Number(crop.storedQty) || 0));
    return !!crop.productionComplete || stored >= cap;
}

export function claimBerryHarvest(state: BerryTreeState): { berryKey: string; qty: number } | null {
    const crop = state.activeCrop;
    if (!crop || crop.storedQty <= 0) return null;
    const qty = Math.floor(crop.storedQty);
    const berryKey = crop.berryKey;
    const cap = Math.max(1, Math.floor(Number(crop.stockCap) || 1));
    const sessionComplete = !!crop.productionComplete || qty >= cap;
    crop.storedQty = 0;
    if (sessionComplete) {
        state.activeCrop = null;
    }
    return { berryKey, qty };
}

export function cancelBerryCrop(state: BerryTreeState): { berryKey: string; qty: number } | null {
    const harvest = claimBerryHarvest(state);
    state.activeCrop = null;
    return harvest;
}

export function setBerryPlantQueue(state: BerryTreeState, berryKey: string): boolean {
    const maxSize = getMaxPlantQueueSize(state);
    if (maxSize <= 0) return false;
    const key = String(berryKey);
    if (!isBerryUnlocked(state, key)) return false;
    if (state.activeCrop?.berryKey === key) return false;

    if (state.plantQueue.length >= maxSize) {
        if (maxSize === 1) {
            state.plantQueue = [key];
            return true;
        }
        return false;
    }
    state.plantQueue.push(key);
    return true;
}

export function clearBerryPlantQueue(state: BerryTreeState): void {
    state.plantQueue = [];
}

export function shiftBerryPlantQueue(state: BerryTreeState): string | null {
    return state.plantQueue.shift() ?? null;
}

export function removeFirstBerryFromPlantQueue(state: BerryTreeState, berryKey: string): boolean {
    const idx = state.plantQueue.indexOf(String(berryKey));
    if (idx < 0) return false;
    state.plantQueue.splice(idx, 1);
    return true;
}

export function purchaseBerryPlantQueueUpgrade(state: BerryTreeState): boolean {
    if (!state || typeof state !== 'object') return false;
    if (state.plantQueueLevel >= BERRY_TREE.plantQueueMaxLevels) return false;
    state.plantQueueLevel += 1;
    return true;
}

export function canPurchaseBerryPlantQueueUpgrade(
    state: BerryTreeState,
    ownedMoomooMilk: number,
    farmLevel: number,
): boolean {
    if (!state || typeof state !== 'object') return false;
    if (state.plantQueueLevel >= BERRY_TREE.plantQueueMaxLevels) return false;
    const cost = getPlantQueueUpgradeCostForNextLevel(state);
    return Number.isFinite(farmLevel)
        && farmLevel >= cost.minFarmLevel
        && Number.isFinite(ownedMoomooMilk)
        && ownedMoomooMilk >= cost.moomoo_milk;
}

export function getBerryTreeHotspotStoredQty(state: BerryTreeState): number {
    return Math.max(0, Math.floor(Number(state.activeCrop?.storedQty) || 0));
}

export function countUnlockedBerries(state: BerryTreeState): number {
    return state.unlockedBerryKeys.length;
}

export function countRevealedSlots(state: BerryTreeState): number {
    let n = 0;
    for (const slots of Object.values(state.revealedSlotsByBerry)) {
        for (const slot of slots) {
            if (slot) n += 1;
        }
    }
    return n;
}
