/**
 * @file src/lib/miltankFarmTalents.ts
 * Miltank farm level + talent tree (pure, Vitest-friendly).
 */

import {
    MILTANK_FARM_TALENTS,
    MILTANK_FARM_TALENT_BRANCHES,
    getMiltankFarmLevel,
    getMiltankFarmMaxLevel,
    getXpForNextLevel,
    type MiltankFarmTalentBranch,
} from '../../constants/balance/miltankFarmTalents.ts';
import { MILTANK_FARM } from '../../constants/balance/miltankFarm.ts';
import type { MiltankFarmState, MiltankPastureEntry } from './miltankFarmLogic.ts';
import { syncFarmAggregateLevel, syncPastureEntryProgression } from './miltankFarmLogic.ts';

function ensureEntryTalentRanks(entry: MiltankPastureEntry): Record<string, number> {
    if (!entry.talentRanks || typeof entry.talentRanks !== 'object') {
        entry.talentRanks = {};
    }
    return entry.talentRanks;
}

export function syncMiltankFarmProgression(state: MiltankFarmState): void {
    if (!state || typeof state !== 'object') return;
    if (!state.talentRanks || typeof state.talentRanks !== 'object') {
        state.talentRanks = {};
    }
    if (Array.isArray(state.pastureEntries)) {
        for (const entry of state.pastureEntries) {
            if (entry && typeof entry === 'object') {
                ensureEntryTalentRanks(entry);
                syncPastureEntryProgression(entry);
            }
        }
    }
    syncFarmAggregateLevel(state);
}

export function getTalentRank(entry: MiltankPastureEntry, branch: MiltankFarmTalentBranch): number {
    if (!entry || typeof entry !== 'object') return 0;
    const raw = Number(entry.talentRanks?.[branch]);
    return Number.isFinite(raw) ? Math.max(0, Math.floor(raw)) : 0;
}

export function getTotalTalentPointsEarned(level: number): number {
    const raw = Number(level);
    const safeLevel = Number.isFinite(raw) ? Math.max(0, Math.floor(raw)) : 0;
    return safeLevel * MILTANK_FARM_TALENTS.talentPointsPerLevel;
}

export function getSpentTalentPointsForEntry(entry: MiltankPastureEntry): number {
    if (!entry || typeof entry !== 'object') return 0;
    const ranks = entry.talentRanks ?? {};
    return Object.values(ranks).reduce((sum, v) => {
        const raw = Number(v);
        return sum + (Number.isFinite(raw) ? Math.max(0, Math.floor(raw)) : 0);
    }, 0);
}

export function getUnspentTalentPoints(entry: MiltankPastureEntry): number {
    if (!entry || typeof entry !== 'object') return 0;
    syncPastureEntryProgression(entry);
    return Math.max(0, getTotalTalentPointsEarned(entry.level) - getSpentTalentPointsForEntry(entry));
}

export function canInvestTalentForEntry(entry: MiltankPastureEntry, branch: MiltankFarmTalentBranch): boolean {
    if (getUnspentTalentPoints(entry) <= 0) return false;
    const def = MILTANK_FARM_TALENT_BRANCHES[branch];
    if (!def) return false;
    return getTalentRank(entry, branch) < def.maxRank;
}

export function investMiltankFarmTalentForEntry(
    entry: MiltankPastureEntry,
    branch: MiltankFarmTalentBranch,
): boolean {
    if (!canInvestTalentForEntry(entry, branch)) return false;
    const ranks = ensureEntryTalentRanks(entry);
    ranks[branch] = getTalentRank(entry, branch) + 1;
    return true;
}

export function getProductionTalentMult(entry: MiltankPastureEntry): number {
    return getTalentRank(entry, 'production') * MILTANK_FARM_TALENTS.productionPerRank;
}

export function getLevelProductionMult(entry: MiltankPastureEntry): number {
    if (!entry || typeof entry !== 'object') return 0;
    const raw = Number(entry.level);
    const safeLevel = Number.isFinite(raw) ? Math.max(0, Math.floor(raw)) : 0;
    return safeLevel * MILTANK_FARM_TALENTS.productionPerLevel;
}

/** Per-Miltank milk potency rank bonus (+0.1 % / rank). */
export function getMilkPotencyVitaminBonus(entry: MiltankPastureEntry): number {
    if (!entry || typeof entry !== 'object') return 0;
    return getTalentRank(entry, 'milk_potency') * MILTANK_FARM_TALENTS.milkPotencyPerRank;
}

export function getMilkPotencyVitaminBonusTotal(state: MiltankFarmState | null | undefined): number {
    if (!state || typeof state !== 'object') return 0;
    syncMiltankFarmProgression(state);
    let total = 0;
    if (Array.isArray(state.pastureEntries)) {
        for (const entry of state.pastureEntries) {
            if (entry && typeof entry === 'object') {
                total += getMilkPotencyVitaminBonus(entry);
            }
        }
    }
    return total;
}

/** Total vitamin efficiency granted per moomoo milk consumed (base 3 % + sum of all Miltank potency). */
export function getMoomooMilkVitaminBonusPerUse(state: MiltankFarmState | null | undefined): number {
    return MILTANK_FARM_TALENTS.moomooMilkBaseVitaminEfficiency + getMilkPotencyVitaminBonusTotal(state);
}

export function getMoomooMilkConsumedCount(stats: unknown): number {
    if (!stats || typeof stats !== 'object') return 0;
    const consumed = (stats as { vitaminsConsumed?: Record<string, unknown> }).vitaminsConsumed;
    if (!consumed || typeof consumed !== 'object') return 0;
    const raw = Number(consumed.moomooMilk);
    return Number.isFinite(raw) ? Math.max(0, Math.floor(raw)) : 0;
}

export function computeVitaminEfficiencyFromMilkCount(
    moomooMilkCount: number,
    state: MiltankFarmState | null | undefined,
): number {
    const raw = Number(moomooMilkCount);
    const count = Number.isFinite(raw) ? Math.max(0, Math.floor(raw)) : 0;
    return count * getMoomooMilkVitaminBonusPerUse(state);
}

export interface MilkPotencyVitaminEfficiencySyncTarget {
    vitaminEfficiency?: number;
    miltankFarmState?: MiltankFarmState | null;
    stats?: unknown;
}

const LEGACY_MILK_EFF_EPSILON = 1e-9;

function ensureVitaminsConsumed(stats: Record<string, unknown>): Record<string, number> {
    if (!stats.vitaminsConsumed || typeof stats.vitaminsConsumed !== 'object') {
        stats.vitaminsConsumed = {
            hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0, all: 0, moomooMilk: 0,
        };
    }
    return stats.vitaminsConsumed as Record<string, number>;
}

function resolveMoomooMilkPerUseRate(state: MiltankFarmState | null | undefined): number {
    return Math.max(
        MILTANK_FARM_TALENTS.moomooMilkBaseVitaminEfficiency,
        getMoomooMilkVitaminBonusPerUse(state),
    );
}

/**
 * Backfill stats.vitaminsConsumed.moomooMilk from legacy vitaminEfficiency when the counter
 * was never tracked (pre-milk_potency saves) or is lower than the stored efficiency.
 */
export function migrateLegacyMoomooMilkCount(target: MilkPotencyVitaminEfficiencySyncTarget): void {
    const legacyEff = Math.max(0, Number(target.vitaminEfficiency) || 0);
    if (legacyEff <= LEGACY_MILK_EFF_EPSILON) return;

    const state = target.miltankFarmState ?? null;
    const count = getMoomooMilkConsumedCount(target.stats);
    const computed = computeVitaminEfficiencyFromMilkCount(count, state);
    if (count > 0 && computed >= legacyEff - LEGACY_MILK_EFF_EPSILON) return;

    const perUse = resolveMoomooMilkPerUseRate(state);
    const estimatedFromLegacy = Math.round(legacyEff / perUse);
    const nextCount = Math.max(count, estimatedFromLegacy);
    if (nextCount <= 0) return;

    if (!target.stats || typeof target.stats !== 'object') {
        target.stats = { vitaminsConsumed: { moomooMilk: nextCount } };
        return;
    }
    const consumed = ensureVitaminsConsumed(target.stats as Record<string, unknown>);
    consumed.moomooMilk = nextCount;
}

/** Recompute vitaminEfficiency from milk count × per-use bonus (retroactive on talent invest). */
export function syncVitaminEfficiencyFromMilkPotency(target: MilkPotencyVitaminEfficiencySyncTarget): number {
    migrateLegacyMoomooMilkCount(target);
    const count = getMoomooMilkConsumedCount(target.stats);
    const next = computeVitaminEfficiencyFromMilkCount(count, target.miltankFarmState ?? null);
    target.vitaminEfficiency = next;
    return next;
}

export function getCareSatietyDecayMult(entry: MiltankPastureEntry): number {
    const rank = Math.min(3, getTalentRank(entry, 'care'));
    return 1 - rank * MILTANK_FARM_TALENTS.careSatietyDecayReductionPerRank;
}

export function getCareFeedBoostDurationMult(entry: MiltankPastureEntry): number {
    const rank = Math.max(0, Math.min(2, getTalentRank(entry, 'care') - 3));
    return 1 + rank * MILTANK_FARM_TALENTS.careFeedBoostDurationPerRank;
}

export function getCareFeedXpBonus(entry: MiltankPastureEntry): number {
    return getTalentRank(entry, 'care') >= 6 ? MILTANK_FARM_TALENTS.careFeedXpBonus : 0;
}

export function getCareSatietyCapBonus(entry: MiltankPastureEntry): number {
    return getTalentRank(entry, 'care') >= 7 ? MILTANK_FARM_TALENTS.careSatietyCapBonus : 0;
}

export function getEntrySatietyMax(entry: MiltankPastureEntry): number {
    return MILTANK_FARM.satietyMax + getCareSatietyCapBonus(entry);
}

export function resolveMaxAssignableSlots(state: MiltankFarmState): number {
    return state.unlocked ? 2 : 0;
}

export function getPastureEntryXpProgress(entry: MiltankPastureEntry): {
    level: number;
    xp: number;
    xpToNext: number | null;
    xpInLevel: number;
    xpNeededInLevel: number | null;
} {
    const level = Math.max(0, entry.level);
    const xp = Math.max(0, Math.floor(Number(entry.xp) || 0));
    const currentThreshold = MILTANK_FARM_TALENTS.levelXpThresholds[level] ?? 0;
    const xpToNext = getXpForNextLevel(level);
    if (xpToNext == null) {
        return { level, xp, xpToNext: null, xpInLevel: 0, xpNeededInLevel: null };
    }
    return {
        level,
        xp,
        xpToNext,
        xpInLevel: xp - currentThreshold,
        xpNeededInLevel: xpToNext - currentThreshold,
    };
}

export function getXpProgress(state: MiltankFarmState): {
    level: number;
    xp: number;
    xpToNext: number | null;
    xpInLevel: number;
    xpNeededInLevel: number | null;
} {
    syncMiltankFarmProgression(state);
    const level = state.level;
    const xp = Math.max(0, Math.floor(Number(state.xp) || 0));
    const currentThreshold = MILTANK_FARM_TALENTS.levelXpThresholds[level] ?? 0;
    const xpToNext = getXpForNextLevel(level);
    if (xpToNext == null) {
        return { level, xp, xpToNext: null, xpInLevel: 0, xpNeededInLevel: null };
    }
    return {
        level,
        xp,
        xpToNext,
        xpInLevel: xp - currentThreshold,
        xpNeededInLevel: xpToNext - currentThreshold,
    };
}

export { getMiltankFarmLevel, getMiltankFarmMaxLevel, type MiltankFarmTalentBranch };
