/**
 * @file src/lib/miltankFarmDisplay.ts
 * Pure display helpers for Miltank farm UI (Vitest-friendly).
 */

import { MILTANK_FARM, type MiltankFarmRequestCategory } from '../../constants/balance/miltankFarm.ts';
import { getSatietyFeedRoom } from './miltankFarmLogic.ts';
import type { MiltankFarmTalentBranch } from './miltankFarmTalents.ts';

export type MiltankFeedBlockedReason = 'none' | 'no_request' | 'missing_items' | 'satiety';

const REQUEST_MIN_LEVEL: Record<MiltankFarmRequestCategory, number> = {
    common: 0,
    medium: 2,
    rare: 4,
    premium: 6,
};

export function getRequestMinFarmLevel(category: string): number {
    const key = category as MiltankFarmRequestCategory;
    return REQUEST_MIN_LEVEL[key] ?? 0;
}

/** Player-facing satiety: fractional decay should not drop the bar until a full point is lost. */
export function getDisplaySatiety(satiety: number, satietyMax: number = MILTANK_FARM.satietyMax): number {
    const value = Number(satiety) || 0;
    if (value <= 0) return 0;
    return Math.min(satietyMax, Math.ceil(value - 1e-9));
}

/** Player-facing whole-number percent (ceil so small bonuses are not truncated). */
export function formatDisplayPercentCeil(ratio: number): string {
    const pct = Math.ceil(Math.max(0, Number(ratio) || 0) * 100 - 1e-9);
    return String(pct);
}

/** Milk potency / vitamin rates: one decimal when below 10 % (0.1 % steps). */
export function formatMilkVitaminPercent(ratio: number): string {
    const pct = Math.max(0, Number(ratio) || 0) * 100;
    if (pct < 10) return pct.toFixed(1).replace(/\.0$/, '');
    return formatDisplayPercentCeil(ratio);
}

export function formatFarmDuration(ms: number, lang: 'fr' | 'en' = 'fr'): string {
    if (ms <= 0) return lang === 'en' ? 'now' : 'maintenant';
    const totalMin = Math.ceil(ms / 60_000);
    const h = Math.floor(totalMin / 60);
    const m = totalMin % 60;
    if (h > 0 && m > 0) return lang === 'en' ? `${h}h ${m}m` : `${h} h ${m}`;
    if (h > 0) return lang === 'en' ? `${h}h` : `${h} h`;
    return lang === 'en' ? `${m}m` : `${m} min`;
}

export function getSatietyRoomMs(
    satiety: number,
    requestCategory?: string | null,
    satietyMax: number = MILTANK_FARM.satietyMax,
    decayMult: number = 1,
): number {
    const effectiveDecay = MILTANK_FARM.satietyDecayPerHour * Math.max(0.01, Number(decayMult) || 1);
    const hoursPerPoint = 1 / effectiveDecay;
    if (requestCategory) {
        const room = getSatietyFeedRoom(satiety, requestCategory, satietyMax);
        if (room >= 0) return 0;
        return Math.ceil(-room * hoursPerPoint * 3_600_000);
    }
    if (Math.floor(Number(satiety) || 0) < satietyMax) return 0;
    return Math.ceil(hoursPerPoint * 3_600_000);
}

export function getCareSatietyDecayPct(rank: number): number {
    return Math.min(3, Math.max(0, Math.floor(Number(rank) || 0))) * 10;
}

export function getCareBoostDurationPct(rank: number): number {
    const boostRanks = Math.max(0, Math.min(2, Math.floor(Number(rank) || 0) - 3));
    return boostRanks * 15;
}

export function getCareTalentCurrentBonusKey(rank: number): string {
    const r = Math.max(0, Math.floor(Number(rank) || 0));
    if (r <= 0) return 'miltankFarm.talent.careTagline';
    if (r <= 3) return 'miltankFarm.talent.careCurrentDecay';
    if (r <= 5) return 'miltankFarm.talent.careCurrentBoost';
    if (r === 6) return 'miltankFarm.talent.careCurrentXp';
    return 'miltankFarm.talent.careCurrentCap';
}

export function getCareTalentCurrentBonusFallback(rank: number, lang: 'fr' | 'en'): string {
    const r = Math.max(0, Math.floor(Number(rank) || 0));
    if (r <= 0) {
        return lang === 'en'
            ? 'Easier feeding and faster leveling for this Miltank'
            : 'Nourriture et montée de niveau facilitées pour ce Miltank';
    }
    if (r <= 3) {
        const pct = r * 10;
        return lang === 'en' ? `+${pct}% fuller for longer` : `+${pct} % durée de satiété`;
    }
    if (r <= 5) {
        const pct = (r - 3) * 15;
        return lang === 'en' ? `+${pct}% feed boost duration` : `+${pct} % durée boost nourriture`;
    }
    if (r === 6) {
        return lang === 'en' ? '+1 XP per feed' : '+1 XP par nourriture';
    }
    return lang === 'en' ? '+10 max satiety' : '+10 satiété max';
}

export function getCareTalentCurrentBonusVars(rank: number): Record<string, string | number> {
    const r = Math.max(0, Math.floor(Number(rank) || 0));
    if (r <= 3) return { pct: r * 10 };
    if (r <= 5) return { pct: (r - 3) * 15 };
    if (r >= 7) return { max: MILTANK_FARM.satietyMax + 10 };
    return {};
}

export function getFeedBlockedReason(
    entrySatiety: number,
    requestKey: string | null,
    requestQty: number,
    owned: number,
    requestCategory?: string | null,
    satietyMax: number = MILTANK_FARM.satietyMax,
): MiltankFeedBlockedReason {
    if (!requestKey) return 'no_request';
    if (requestCategory && getSatietyFeedRoom(entrySatiety, requestCategory, satietyMax) < 0) return 'satiety';
    if (!requestCategory && Math.floor(Number(entrySatiety) || 0) >= satietyMax) {
        return 'satiety';
    }
    if (owned < requestQty) return 'missing_items';
    return 'none';
}

export function computeNextMilkMs(
    storedMilk: number,
    pendingMilk: number,
    stockCap: number,
    milkPerHour: number,
): number | null {
    if (storedMilk >= stockCap || milkPerHour <= 0) return null;
    const fractional = pendingMilk % 1;
    const need = fractional > 0 ? 1 - fractional : 1;
    return Math.ceil((need / milkPerHour) * 3_600_000);
}

/** Player-facing progress (0–100) toward the next whole milk unit. */
export function computeMilkCyclePct(pendingMilk: number): number {
    const pct = Math.min(100, Math.ceil(((pendingMilk % 1) * 100) - 1e-9));
    return pct === 0 ? 0 : pct;
}

/** Player-facing stock fill (0–100), includes fractional pending milk. */
export function computeStockFillPct(stored: number, pending: number, cap: number): number {
    if (cap <= 0) return 0;
    const total = Math.max(0, Number(stored) || 0) + Math.max(0, Number(pending) || 0);
    if (total <= 0) return 0;
    return Math.min(100, Math.ceil((total / cap) * 100 - 1e-9));
}

/** Ms until stored + pending reaches stock cap at constant production rate. */
export function computeStockFullMs(
    stored: number,
    pending: number,
    cap: number,
    milkPerHour: number,
): number | null {
    if (cap <= 0 || milkPerHour <= 0) return null;
    const room = cap - (Number(stored) || 0) - (Number(pending) || 0);
    if (room <= 0) return null;
    return Math.ceil((room / milkPerHour) * 3_600_000);
}

export function getCareTalentNextBonusKey(rank: number): string {
    const nextRank = rank + 1;
    if (nextRank <= 3) return 'miltankFarm.talent.careNextSatiety';
    if (nextRank <= 5) return 'miltankFarm.talent.careNextBoost';
    if (nextRank === 6) return 'miltankFarm.talent.careNextXp';
    if (nextRank === 7) return 'miltankFarm.talent.careNextCap';
    return 'miltankFarm.talent.careMaxed';
}

export function getCareTalentNextBonusFallback(rank: number, lang: 'fr' | 'en'): string {
    const nextRank = rank + 1;
    if (nextRank <= 3) {
        return lang === 'en' ? 'Next: +10% fuller for longer' : 'Suivant : +10 % durée de satiété';
    }
    if (nextRank <= 5) {
        return lang === 'en' ? 'Next: +15% feed boost duration' : 'Suivant : +15 % durée boost nourriture';
    }
    if (nextRank === 6) {
        return lang === 'en' ? 'Next: +1 XP per feed' : 'Suivant : +1 XP par nourriture';
    }
    if (nextRank === 7) {
        return lang === 'en' ? 'Next: +10 max satiety' : 'Suivant : +10 satiété max';
    }
    return lang === 'en' ? 'Max rank' : 'Rang max';
}

export function getTalentBranchSummary(
    branch: MiltankFarmTalentBranch,
    rank: number,
    milkPotencyPct: string,
): string {
    if (branch === 'production') {
        const pct = (rank * 3).toFixed(0);
        return `+${pct}%`;
    }
    if (branch === 'milk_potency') {
        return `${milkPotencyPct}%`;
    }
    if (branch === 'care') {
        if (rank <= 0) return '';
        if (rank <= 3) return `+${rank * 10}% full`;
        if (rank <= 5) return `+${(rank - 3) * 15}% boost`;
        if (rank === 6) return '+1 XP';
        if (rank >= 7) return '+10 sat.';
    }
    return '';
}
