/**
 * @file src/lib/miltankFarmThreats.ts
 * Pure pasture threat / guardian logic (Vitest-friendly).
 */

import {
    MILTANK_FARM_THREATS,
    type FarmThreatType,
    isGuardianSpeciesName,
    clampThreatLevel,
    pickWeightedPredator,
} from '../../constants/balance/miltankFarmThreats.ts';
import type { CreatureData } from '../types/creature.js';
import type { MiltankFarmState, MiltankPastureEntry } from './miltankFarmLogic.ts';
import { getMiltankFarmSpeciesKey, getNarrativePastureEntry, normalizeMiltankFarmState } from './miltankFarmLogic.ts';

export type FarmThreatApproachSide = 'left' | 'right';

export interface MiltankFarmGuardianAssignment {
    pastureUid: string;
    creature: CreatureData;
}

export interface MiltankFarmDebuff {
    pastureUid: string;
    type: 'predator';
    predatorSpecies: string;
    productionMult: number;
    until: number;
}

export interface FarmIncidentPulse {
    pastureUid: string;
    type: 'predator' | 'rocket' | 'repelled';
    predatorSpecies?: string;
    repelledThreat?: FarmThreatType;
    milkStolen?: number;
    at: number;
}

export interface FarmPendingIncidentAlert {
    pastureUid: string;
    type: 'predator' | 'rocket';
    predatorSpecies?: string;
    milkStolen?: number;
    at: number;
}

export interface FarmThreatApproach {
    id: string;
    pastureUid: string;
    type: FarmThreatType;
    species: string;
    threatLevel: number;
    startedAt: number;
    durationMs: number;
    /** Edge of the pasture scene the threat walks in from. */
    approachSide?: FarmThreatApproachSide;
}

export function normalizeThreatApproachSide(
    approach: Pick<FarmThreatApproach, 'approachSide'>,
): FarmThreatApproachSide {
    return approach.approachSide === 'right' ? 'right' : 'left';
}

export interface FarmThreatTickContext {
    teamRocketUnlocked: boolean;
    pastureQuestCompleted: boolean;
}

export interface FarmIncidentRollResult {
    pulses: FarmIncidentPulse[];
    incidentsApplied: number;
    approachesSpawned: number;
    spawnedApproaches: FarmThreatApproach[];
}

let threatIdCounter = 0;

export function resetFarmThreatIdCounterForTests(): void {
    threatIdCounter = 0;
}

function nextThreatId(now: number): string {
    threatIdCounter += 1;
    return `farm-threat-${now}-${threatIdCounter}`;
}

export function isGuardianSpecies(creature: CreatureData | null | undefined): boolean {
    return isGuardianSpeciesName(getMiltankFarmSpeciesKey(creature));
}

export function getGuardianForPastureUid(
    state: MiltankFarmState,
    pastureUid: string,
): CreatureData | null {
    const assignments = state.guardianAssignments ?? [];
    const found = assignments.find((a) => a.pastureUid === pastureUid);
    return found?.creature ?? null;
}

export function areFarmThreatsUnlocked(state: MiltankFarmState): boolean {
    normalizeMiltankFarmState(state);
    if (!state.unlocked) return false;
    return getNarrativePastureEntry(state).level >= MILTANK_FARM_THREATS.unlockMinThreatLevel;
}

export function areGuardiansUnlocked(
    state: MiltankFarmState,
    ctx: Pick<FarmThreatTickContext, 'pastureQuestCompleted'>,
): boolean {
    normalizeMiltankFarmState(state);
    if (!state.unlocked) return false;
    return ctx.pastureQuestCompleted;
}

export function getRocketEligiblePastureUids(state: MiltankFarmState): string[] {
    normalizeMiltankFarmState(state);
    return (state.pastureEntries ?? [])
        .filter((e) => Math.floor(Number(e.storedMilk) || 0) >= 1)
        .map((e) => e.uid);
}

export function pickIncidentType(
    teamRocketUnlocked: boolean,
    entryHasStock: boolean,
    rng: () => number = Math.random,
): FarmThreatType | null {
    const predatorW = MILTANK_FARM_THREATS.predatorWeight;
    const rocketW = teamRocketUnlocked && entryHasStock ? MILTANK_FARM_THREATS.rocketWeight : 0;
    const total = predatorW + rocketW;
    if (total <= 0) return null;
    const roll = rng() * total;
    return roll < predatorW ? 'predator' : 'rocket';
}

export function getPastureProductionMult(
    state: MiltankFarmState,
    pastureUid: string,
    now: number,
): number {
    pruneExpiredDebuffs(state, now);
    const debuff = (state.activeDebuffs ?? []).find(
        (d) => d.pastureUid === pastureUid && d.until > now,
    );
    return debuff ? debuff.productionMult : 1;
}

export function pruneExpiredDebuffs(state: MiltankFarmState, now: number): void {
    if (!Array.isArray(state.activeDebuffs)) return;
    state.activeDebuffs = state.activeDebuffs.filter((d) => d.until > now);
}

export function applyPredatorIncident(
    state: MiltankFarmState,
    pastureUid: string,
    predatorSpecies: string,
    now: number,
): void {
    if (!Array.isArray(state.activeDebuffs)) state.activeDebuffs = [];
    state.activeDebuffs = state.activeDebuffs.filter((d) => d.pastureUid !== pastureUid);
    state.activeDebuffs.push({
        pastureUid,
        type: 'predator',
        predatorSpecies,
        productionMult: MILTANK_FARM_THREATS.predatorProdMult,
        until: now + MILTANK_FARM_THREATS.predatorDurationMs,
    });
}

export type PastureDebuffHealResult =
    | { ok: true; removed: boolean; remainingMs: number; reducedMs: number }
    | { ok: false; reason: 'no_debuff' | 'invalid_item' };

export function getPastureHealReductionPct(itemKey: string): number | null {
    const items = MILTANK_FARM_THREATS.pastureHealItems as Record<string, number>;
    const pct = items[itemKey];
    return typeof pct === 'number' && pct > 0 ? pct : null;
}

export function applyPastureDebuffHeal(
    state: MiltankFarmState,
    pastureUid: string,
    itemKey: string,
    now: number,
): PastureDebuffHealResult {
    const pct = getPastureHealReductionPct(itemKey);
    if (pct == null) return { ok: false, reason: 'invalid_item' };

    const debuff = getActiveDebuffForPasture(state, pastureUid, now);
    if (!debuff) return { ok: false, reason: 'no_debuff' };

    const reducedMs = Math.floor(MILTANK_FARM_THREATS.predatorDurationMs * pct);
    const newUntil = debuff.until - reducedMs;
    if (newUntil <= now) {
        state.activeDebuffs = (state.activeDebuffs ?? []).filter(
            (d) => !(d.pastureUid === pastureUid && d.type === 'predator'),
        );
        return { ok: true, removed: true, remainingMs: 0, reducedMs };
    }
    debuff.until = newUntil;
    return { ok: true, removed: false, remainingMs: newUntil - now, reducedMs };
}

export function applyRocketTheft(
    state: MiltankFarmState,
    pastureUid: string,
    rng: () => number = Math.random,
): number {
    const entry = state.pastureEntries?.find((e) => e.uid === pastureUid);
    if (!entry) return 0;
    const stored = Math.floor(Number(entry.storedMilk) || 0);
    if (stored < 1) return 0;
    const min = MILTANK_FARM_THREATS.rocketStealMin;
    const max = MILTANK_FARM_THREATS.rocketStealMax;
    const steal = min + Math.floor(rng() * (max - min + 1));
    const taken = Math.min(stored, steal);
    entry.storedMilk = stored - taken;
    return taken;
}

function entryHasStoredMilk(entry: MiltankPastureEntry): boolean {
    return Math.floor(Number(entry.storedMilk) || 0) >= 1;
}

function pushPulse(state: MiltankFarmState, pulse: FarmIncidentPulse): void {
    if (!Array.isArray(state.pendingIncidentPulses)) state.pendingIncidentPulses = [];
    state.pendingIncidentPulses.push(pulse);
    const cutoff = pulse.at - MILTANK_FARM_THREATS.incidentPulseTtlMs;
    state.pendingIncidentPulses = state.pendingIncidentPulses.filter((p) => p.at >= cutoff);
}

export function hasActiveThreatApproachForPasture(
    state: MiltankFarmState,
    pastureUid: string,
): boolean {
    return (state.activeThreatApproaches ?? []).some((a) => a.pastureUid === pastureUid);
}

export function getThreatApproachById(
    state: MiltankFarmState,
    threatId: string,
): FarmThreatApproach | null {
    return (state.activeThreatApproaches ?? []).find((a) => a.id === threatId) ?? null;
}

export function removeThreatApproach(state: MiltankFarmState, threatId: string): FarmThreatApproach | null {
    const list = state.activeThreatApproaches ?? [];
    const idx = list.findIndex((a) => a.id === threatId);
    if (idx < 0) return null;
    const [removed] = list.splice(idx, 1);
    state.activeThreatApproaches = list;
    return removed ?? null;
}

function spawnThreatApproach(
    state: MiltankFarmState,
    pastureUid: string,
    type: FarmThreatType,
    species: string,
    threatLevel: number,
    now: number,
    rng: () => number = Math.random,
): FarmThreatApproach | null {
    if (hasActiveThreatApproachForPasture(state, pastureUid)) return null;
    if (!Array.isArray(state.activeThreatApproaches)) state.activeThreatApproaches = [];
    const approach: FarmThreatApproach = {
        id: nextThreatId(now),
        pastureUid,
        type,
        species,
        threatLevel: clampThreatLevel(threatLevel),
        startedAt: now,
        durationMs: MILTANK_FARM_THREATS.approachDurationMs,
        approachSide: rng() < 0.5 ? 'left' : 'right',
    };
    state.activeThreatApproaches.push(approach);
    return approach;
}

export function getThreatApproachProgress(approach: FarmThreatApproach, now: number): number {
    const elapsed = Math.max(0, now - approach.startedAt);
    if (approach.durationMs <= 0) return 1;
    return Math.max(0, Math.min(1, elapsed / approach.durationMs));
}

export function getExpiredThreatApproaches(
    state: MiltankFarmState,
    now: number,
): FarmThreatApproach[] {
    const list = state.activeThreatApproaches ?? [];
    return list.filter((a) => now >= a.startedAt + a.durationMs);
}

export function applyThreatApproachIncident(
    state: MiltankFarmState,
    approach: FarmThreatApproach,
    now: number,
    rng: () => number = Math.random,
): FarmIncidentPulse | null {
    if (approach.type === 'rocket') {
        const stolen = applyRocketTheft(state, approach.pastureUid, rng);
        if (stolen <= 0) return null;
        const pulse: FarmIncidentPulse = {
            pastureUid: approach.pastureUid,
            type: 'rocket',
            milkStolen: stolen,
            at: now,
        };
        pushPulse(state, pulse);
        return pulse;
    }
    applyPredatorIncident(state, approach.pastureUid, approach.species, now);
    const pulse: FarmIncidentPulse = {
        pastureUid: approach.pastureUid,
        type: 'predator',
        predatorSpecies: approach.species,
        at: now,
    };
    pushPulse(state, pulse);
    return pulse;
}

export function setFarmIncidentAlert(state: MiltankFarmState, pulse: FarmIncidentPulse): void {
    if (pulse.type !== 'predator' && pulse.type !== 'rocket') return;
    state.pendingIncidentAlert = {
        pastureUid: pulse.pastureUid,
        type: pulse.type,
        predatorSpecies: pulse.predatorSpecies,
        milkStolen: pulse.milkStolen,
        at: pulse.at,
    };
}

export function clearFarmIncidentAlert(state: MiltankFarmState): void {
    state.pendingIncidentAlert = null;
}

export function buildRepelledPulse(
    pastureUid: string,
    repelledThreat: FarmThreatType,
    predatorSpecies: string | undefined,
    now: number,
): FarmIncidentPulse {
    return {
        pastureUid,
        type: 'repelled',
        repelledThreat,
        predatorSpecies,
        at: now,
    };
}

function recordRepelled(state: MiltankFarmState, pulse: FarmIncidentPulse): void {
    pushPulse(state, pulse);
    state.incidentsRepelled = (Number(state.incidentsRepelled) || 0) + 1;
}

function runSingleIncidentCheck(
    state: MiltankFarmState,
    ctx: FarmThreatTickContext,
    now: number,
    pulses: FarmIncidentPulse[],
    spawnedApproaches: FarmThreatApproach[],
    rng: () => number,
): { incidentsApplied: number; approachesSpawned: number } {
    const incidentsApplied = 0;
    let approachesSpawned = 0;
    const entries = state.pastureEntries ?? [];

    for (const entry of entries) {
        if (rng() >= MILTANK_FARM_THREATS.baseIncidentChancePerCheck) continue;

        const hasStock = entryHasStoredMilk(entry);
        const incidentType = pickIncidentType(ctx.teamRocketUnlocked, hasStock, rng);
        if (!incidentType) continue;

        if (incidentType === 'rocket') {
            const threatLevel = MILTANK_FARM_THREATS.rocketThreatLevel;
            if (!hasStock) continue;
            const approach = spawnThreatApproach(
                state,
                entry.uid,
                'rocket',
                'Team Rocket',
                threatLevel,
                now,
                rng,
            );
            if (approach) {
                approachesSpawned += 1;
                spawnedApproaches.push(approach);
            }
            continue;
        }

        const predator = pickWeightedPredator(rng);
        const approach = spawnThreatApproach(
            state,
            entry.uid,
            'predator',
            predator.species,
            predator.threatLevel,
            now,
            rng,
        );
        if (approach) {
            approachesSpawned += 1;
            spawnedApproaches.push(approach);
        }
    }

    return { incidentsApplied, approachesSpawned };
}

export function rollFarmIncidents(
    state: MiltankFarmState,
    elapsedMs: number,
    ctx: FarmThreatTickContext,
    now: number,
    rng: () => number = Math.random,
): FarmIncidentRollResult {
    normalizeMiltankFarmState(state);
    pruneExpiredDebuffs(state, now);

    const pulses: FarmIncidentPulse[] = [];
    const emptyRoll: FarmIncidentRollResult = {
        pulses,
        incidentsApplied: 0,
        approachesSpawned: 0,
        spawnedApproaches: [],
    };
    if (!state.unlocked || !areFarmThreatsUnlocked(state)) {
        return emptyRoll;
    }

    const entries = state.pastureEntries ?? [];
    if (entries.length === 0) return emptyRoll;

    const interval = MILTANK_FARM_THREATS.incidentCheckIntervalMs;
    if (elapsedMs <= 0) {
        return emptyRoll;
    }

    let accumulator = Math.max(0, Number(state.incidentCheckAccumulatorMs) || 0) + elapsedMs;
    let checks = 0;
    while (accumulator >= interval) {
        accumulator -= interval;
        checks += 1;
    }
    state.incidentCheckAccumulatorMs = accumulator;

    if (checks <= 0) {
        return emptyRoll;
    }

    const isLongOffline = elapsedMs > interval * 2;
    if (isLongOffline) {
        const maxOffline = MILTANK_FARM_THREATS.offlineMaxIncidentsPer8h;
        const windows = Math.ceil(elapsedMs / MILTANK_FARM_THREATS.offlineIncidentWindowMs);
        const cap = Math.max(1, maxOffline * windows);
        checks = Math.min(checks, cap);
    }

    let incidentsApplied = 0;
    let approachesSpawned = 0;
    const spawnedApproaches: FarmThreatApproach[] = [];

    for (let c = 0; c < checks; c++) {
        const result = runSingleIncidentCheck(state, ctx, now, pulses, spawnedApproaches, rng);
        incidentsApplied += result.incidentsApplied;
        approachesSpawned += result.approachesSpawned;
    }

    state.lastIncidentRollAt = now;
    return { pulses, incidentsApplied, approachesSpawned, spawnedApproaches };
}

/** Remove guardians for missing pasture uids; returns creatures to return to storage. */
export function evictOrphanGuardians(state: MiltankFarmState): CreatureData[] {
    normalizeMiltankFarmState(state);
    const validUids = new Set((state.pastureEntries ?? []).map((e) => e.uid));
    const assignments = state.guardianAssignments ?? [];
    const kept: MiltankFarmGuardianAssignment[] = [];
    const evicted: CreatureData[] = [];
    const seenPasture = new Set<string>();

    for (const assignment of assignments) {
        if (!assignment?.creature?.uid) continue;
        if (!validUids.has(assignment.pastureUid) || seenPasture.has(assignment.pastureUid)) {
            evicted.push(assignment.creature);
            continue;
        }
        seenPasture.add(assignment.pastureUid);
        kept.push(assignment);
    }

    state.guardianAssignments = kept;
    return evicted;
}

export function getActiveDebuffForPasture(
    state: MiltankFarmState,
    pastureUid: string,
    now: number,
): MiltankFarmDebuff | null {
    pruneExpiredDebuffs(state, now);
    return (state.activeDebuffs ?? []).find((d) => d.pastureUid === pastureUid) ?? null;
}

export function consumeIncidentPulses(
    state: MiltankFarmState,
    now: number,
): FarmIncidentPulse[] {
    if (!Array.isArray(state.pendingIncidentPulses)) return [];
    const cutoff = now - MILTANK_FARM_THREATS.incidentPulseTtlMs;
    const fresh = state.pendingIncidentPulses.filter((p) => p.at >= cutoff);
    state.pendingIncidentPulses = [];
    return fresh;
}

/** @internal Vitest */
export function spawnThreatApproachForTests(
    state: MiltankFarmState,
    pastureUid: string,
    type: FarmThreatType,
    species: string,
    threatLevel: number,
    now: number,
    rng: () => number = Math.random,
): FarmThreatApproach | null {
    return spawnThreatApproach(state, pastureUid, type, species, threatLevel, now, rng);
}
