/**
 * Miltank Farm talent tree — level points from feeds, 3 branches.
 */

import type { MiltankFarmRequestCategory } from './miltankFarm.ts';

export type MiltankFarmTalentBranch = 'production' | 'milk_potency' | 'care';

export interface MiltankFarmTalentTierDef {
    bonus_type: string;
    value: number;
}

export const MILTANK_FARM_TALENTS = Object.freeze({
    talentPointsPerLevel: 1,
    /** Passive production mult per Miltank level (+0.5 %/level), below productionPerRank. */
    productionPerLevel: 0.005,
    productionPerRank: 0.06,
    milkPotencyPerRank: 0.001,
    moomooMilkBaseVitaminEfficiency: 0.03,
    careSatietyDecayReductionPerRank: 0.10,
    careFeedBoostDurationPerRank: 0.15,
    careFeedXpBonus: 1,
    careSatietyCapBonus: 10,
    productionMaxRank: 10,
    milkPotencyMaxRank: 10,
    careMaxRank: 7,
    requestRotationLevel3Mult: 0.9,
    levelXpThresholds: Object.freeze([
        0, 5, 13, 23, 35, 50, 68, 88, 110, 135, 163, 193, 225, 260, 298, 338, 380, 425, 473, 523, 575,
    ]),
    feedXpByCategory: Object.freeze({
        common: 1,
        medium: 1,
        rare: 2,
        premium: 4,
    } as Record<MiltankFarmRequestCategory, number>),
    feedBoostMultByCategory: Object.freeze({
        common: 1.0,
        medium: 1.0,
        rare: 1.15,
        premium: 1.3,
    } as Record<MiltankFarmRequestCategory, number>),
    feedSatietyByCategory: Object.freeze({
        common: 18,
        medium: 25,
        rare: 35,
        premium: 50,
    } as Record<MiltankFarmRequestCategory, number>),
});

export const MILTANK_FARM_TALENT_BRANCHES: Record<MiltankFarmTalentBranch, {
    maxRank: number;
    tiers: MiltankFarmTalentTierDef[];
}> = Object.freeze({
    production: {
        maxRank: MILTANK_FARM_TALENTS.productionMaxRank,
        tiers: Array.from({ length: MILTANK_FARM_TALENTS.productionMaxRank }, () => ({
            bonus_type: 'prod_mult',
            value: MILTANK_FARM_TALENTS.productionPerRank,
        })),
    },
    milk_potency: {
        maxRank: MILTANK_FARM_TALENTS.milkPotencyMaxRank,
        tiers: Array.from({ length: MILTANK_FARM_TALENTS.milkPotencyMaxRank }, () => ({
            bonus_type: 'milk_vitamin_bonus',
            value: MILTANK_FARM_TALENTS.milkPotencyPerRank,
        })),
    },
    care: {
        maxRank: MILTANK_FARM_TALENTS.careMaxRank,
        tiers: [
            { bonus_type: 'satiety_decay_mult', value: MILTANK_FARM_TALENTS.careSatietyDecayReductionPerRank },
            { bonus_type: 'satiety_decay_mult', value: MILTANK_FARM_TALENTS.careSatietyDecayReductionPerRank },
            { bonus_type: 'satiety_decay_mult', value: MILTANK_FARM_TALENTS.careSatietyDecayReductionPerRank },
            { bonus_type: 'feed_boost_duration', value: MILTANK_FARM_TALENTS.careFeedBoostDurationPerRank },
            { bonus_type: 'feed_boost_duration', value: MILTANK_FARM_TALENTS.careFeedBoostDurationPerRank },
            { bonus_type: 'feed_xp_bonus', value: MILTANK_FARM_TALENTS.careFeedXpBonus },
            { bonus_type: 'satiety_cap', value: MILTANK_FARM_TALENTS.careSatietyCapBonus },
        ],
    },
});

export function getMiltankFarmLevel(xp: number): number {
    const totalXp = Math.max(0, Math.floor(Number(xp) || 0));
    const thresholds = MILTANK_FARM_TALENTS.levelXpThresholds;
    let level = 0;
    for (let i = 1; i < thresholds.length; i++) {
        if (totalXp >= (thresholds[i] ?? 0)) level = i;
    }
    return level;
}

export function getMiltankFarmMaxLevel(): number {
    return MILTANK_FARM_TALENTS.levelXpThresholds.length - 1;
}

export function getXpForNextLevel(level: number): number | null {
    const next = level + 1;
    const thresholds = MILTANK_FARM_TALENTS.levelXpThresholds;
    if (next >= thresholds.length) return null;
    return thresholds[next] ?? null;
}

export function getFeedXpForCategory(category: string): number {
    const key = category as MiltankFarmRequestCategory;
    return MILTANK_FARM_TALENTS.feedXpByCategory[key] ?? 1;
}

export function getFeedBoostCategoryMult(category: string): number {
    const key = category as MiltankFarmRequestCategory;
    return MILTANK_FARM_TALENTS.feedBoostMultByCategory[key] ?? 1;
}

export function getFeedSatietyForCategory(category: string): number {
    const key = category as MiltankFarmRequestCategory;
    return MILTANK_FARM_TALENTS.feedSatietyByCategory[key] ?? 18;
}
