import type { CreatureData } from '../types/creature.js';

type CombatPowerInput = Partial<
  Pick<
    CreatureData,
    'maxHp' | 'attack' | 'defense' | 'speed' | 'spattack' | 'spdefense'
  >
>;

function safeStat(value: unknown): number {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
}

export function getCreatureCombatPower(creature: CombatPowerInput | null | undefined): number {
  if (!creature || typeof creature !== 'object') return 0;
  return (
    safeStat(creature.maxHp) +
    safeStat(creature.attack) +
    safeStat(creature.defense) +
    safeStat(creature.speed) +
    safeStat(creature.spattack) +
    safeStat(creature.spdefense)
  );
}
